import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  Inject,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { Observable, of } from 'rxjs';
import { tap } from 'rxjs/operators';
import { CACHE_MANAGER } from '@nestjs/cache-manager';
import type { Cache } from 'cache-manager';
import { MetricsService } from '../metrics/metrics.service';

export const CACHE_TTL_KEY = 'cache_ttl';

/** Prefix for wallet balance cache keys (path part). Matches buildCacheKey when path is /api/v1/wallets/balance. */
const BALANCE_CACHE_PATH = 'v1/wallets/balance';

/** Cache key for a user's balance response. Use when invalidating after ledger changes (e.g. ride completion). */
export function getBalanceCacheKey(userId: string): string {
  return `cache:${BALANCE_CACHE_PATH}:user:${userId}`;
}

const HEADER_CACHE_PATH = 'v1/users/me/header';

/** Cache key for header badge state. Invalidate after notification read changes. */
export function getHeaderCacheKey(userId: string): string {
  return `cache:${HEADER_CACHE_PATH}:user:${userId}`;
}

/**
 * Builds a cache key for read-only GET endpoints.
 * - User-scoped: path + userId (e.g. users/me, wallets/balance)
 * - Admin list: path + sorted query (e.g. admin/kyc/applications?status=PENDING)
 * - Other: path + query
 * Never caches sensitive data (no PIN, OTP, tokens in key).
 */
function buildCacheKey(request: {
  url?: string;
  user?: { userId?: string };
  query?: Record<string, unknown>;
}): string {
  const url = request.url ?? '';
  const path = url.split('?')[0];
  const userId = request.user?.userId;
  const query = request.query ?? {};
  const normalizedPath = path.replace(/^\/[^/]+\//, ''); // drop api/v1 or similar prefix for stability

  const keys = Object.keys(query).sort();
  const queryString =
    keys.length > 0
      ? keys.map((k) => `${k}=${String(query[k])}`).join('&')
      : '';
  // Admin list endpoints: key by query so different filters get different cache entries
  if (
    normalizedPath.includes('admin') &&
    normalizedPath.includes('applications')
  ) {
    return `cache:${normalizedPath}:q:${queryString || 'all'}`;
  }
  if (userId && typeof userId === 'string') {
    return `cache:${normalizedPath}:user:${userId}`;
  }
  if (queryString) return `cache:${normalizedPath}:q:${queryString}`;
  return `cache:${normalizedPath}`;
}

@Injectable()
export class HttpCacheInterceptor implements NestInterceptor {
  constructor(
    @Inject(CACHE_MANAGER) private readonly cacheManager: Cache,
    private readonly reflector: Reflector,
    private readonly metricsService: MetricsService,
  ) {}

  async intercept(
    context: ExecutionContext,
    next: CallHandler,
  ): Promise<Observable<unknown>> {
    const request = context.switchToHttp().getRequest();
    if (request.method !== 'GET') {
      return next.handle();
    }

    const key = buildCacheKey(request);
    const ttl =
      this.reflector.get<number>(CACHE_TTL_KEY, context.getHandler()) ?? 60;

    try {
      const cached = await this.cacheManager.get(key);
      if (cached !== undefined && cached !== null) {
        this.metricsService.incrementDbCacheHit();
        return of(cached);
      }
    } catch {
      // cache get error: proceed to handler
    }
    this.metricsService.incrementDbCacheMiss();

    return next.handle().pipe(
      tap(async (data) => {
        try {
          await this.cacheManager.set(key, data, ttl * 1000);
        } catch {
          // ignore set errors
        }
      }),
    );
  }
}

/** Parse comma-separated list; empty or missing returns [] */
function parseCorsOrigins(): string[] {
  const raw = process.env.CORS_ORIGINS || '';
  if (!raw.trim()) return [];
  return raw
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
}

const DEV_ONLY_SECRET = 'dev-only-secret-not-for-production';

export const appConfig = {
  port: parseInt(process.env.PORT || '3001', 10),
  env: process.env.NODE_ENV || 'development',
  /** Legacy HS256 material — prefer RS256 JWT_PRIVATE_KEY/JWT_PUBLIC_KEY. Never hardcode in prod. */
  get jwtSecret(): string {
    const fromEnv = (process.env.JWT_SECRET ?? '').trim();
    if (fromEnv) return fromEnv;
    if (process.env.NODE_ENV === 'production') {
      // RS256 keys are the production signing path; do not fall back to a shared default.
      return '';
    }
    return DEV_ONLY_SECRET;
  },
  jwtExpiresIn: process.env.JWT_EXPIRES_IN || '15m',
  apiPrefix: process.env.API_PREFIX || 'api/v1',
  demoOtpCode: process.env.DEMO_OTP_CODE || '',
  otpExpirySeconds: parseInt(process.env.OTP_EXPIRY_SECONDS || '300', 10),
  dailyTransferLimit: Number(process.env.DAILY_TRANSFER_LIMIT || 10000),
  monthlyTransferLimit: Number(process.env.MONTHLY_TRANSFER_LIMIT || 100000),
  maxSingleTransfer: Number(process.env.MAX_SINGLE_TRANSFER || 5000),
  /** CORS: production set CORS_ORIGINS (e.g. https://nexa.ma,https://admin.nexa.ma). Dev allows localhost. */
  get corsOrigins(): string[] {
    return parseCorsOrigins();
  },
  /** Body limit in bytes (JSON/urlencoded). Default 1MB. */
  bodyLimit: parseInt(process.env.BODY_LIMIT || '1048576', 10),
  /** Stays service base URL for cross-service header aggregation. */
  get staysApiBaseUrl(): string {
    return (
      process.env.STAYS_API_BASE_URL || 'http://127.0.0.1:3002/api/v1'
    ).replace(/\/$/, '');
  },
  /** Refresh token validity in seconds. Beta: 7 days. */
  refreshTokenExpiresIn: parseInt(
    process.env.REFRESH_TOKEN_EXPIRES_IN || '604800',
    10,
  ),
  /**
   * Pepper for hashing national_id_number (CNIE). Never log.
   * In production, KYC_HASH_PEPPER must be set (otherwise changing JWT_SECRET would change hashes).
   */
  get kycHashPepper(): string {
    if (process.env.NODE_ENV === 'production' && !process.env.KYC_HASH_PEPPER) {
      throw new Error(
        'KYC_HASH_PEPPER is required in production. Set it so CNIE hashes are stable and independent of JWT_SECRET.',
      );
    }
    return (
      process.env.KYC_HASH_PEPPER || process.env.JWT_SECRET || DEV_ONLY_SECRET
    );
  },
  /**
   * Argon2id hash of the admin password (preferred).
   * Generate with: node -e "require('argon2').hash('your-password').then(console.log)"
   */
  get adminPasswordHash(): string {
    return (process.env.ADMIN_PASSWORD_HASH ?? '').trim();
  },
  /**
   * Legacy plaintext admin password — allowed only outside production.
   * Prefer ADMIN_PASSWORD_HASH.
   */
  get adminPassword(): string {
    return (process.env.ADMIN_PASSWORD ?? '').trim();
  },
  /** Pepper for hashing OTP codes / email verification tokens at rest. */
  get otpPepper(): string {
    const pepper =
      process.env.OTP_PEPPER ||
      process.env.REFRESH_TOKEN_PEPPER ||
      process.env.JWT_SECRET ||
      '';
    if (
      process.env.NODE_ENV === 'production' &&
      !process.env.OTP_PEPPER &&
      !process.env.REFRESH_TOKEN_PEPPER
    ) {
      throw new Error(
        'OTP_PEPPER (or REFRESH_TOKEN_PEPPER) is required in production for hashing one-time codes.',
      );
    }
    return pepper || 'dev-otp-pepper-not-for-production';
  },
  /** Pepper for HMAC of refresh token hashes. Required in production. */
  get refreshTokenPepper(): string {
    const pepper =
      process.env.REFRESH_TOKEN_PEPPER || process.env.JWT_SECRET || '';
    if (
      process.env.NODE_ENV === 'production' &&
      !process.env.REFRESH_TOKEN_PEPPER
    ) {
      throw new Error('REFRESH_TOKEN_PEPPER is required in production.');
    }
    if (!pepper) {
      return 'dev-refresh-pepper-not-for-production';
    }
    return pepper;
  },
  /** Email verification / password-reset style tokens expire after this many seconds (default 1 hour). */
  emailVerificationExpiresSeconds: parseInt(
    process.env.EMAIL_VERIFICATION_EXPIRES_SECONDS || '3600',
    10,
  ),
  /** Single admin email (legacy). Keep empty unless explicitly configured. */
  adminEmail: process.env.ADMIN_EMAIL || '',
  /**
   * Comma-separated admin allowlist from ADMIN_EMAILS.
   * No built-in defaults for security.
   */
  get adminEmails(): string[] {
    const raw = process.env.ADMIN_EMAILS || '';
    const fromEnv = raw
      .split(',')
      .map((s) => s.trim().toLowerCase())
      .filter(Boolean);
    return [...new Set(fromEnv)];
  },
  pinMaxAttempts: parseInt(process.env.PIN_MAX_ATTEMPTS || '5', 10),
  pinAttemptWindowMinutes: parseInt(
    process.env.PIN_ATTEMPT_WINDOW_MINUTES || '15',
    10,
  ),
  pinBaseLockoutSeconds: parseInt(
    process.env.PIN_BASE_LOCKOUT_SECONDS || '60',
    10,
  ),
  pinMaxLockoutSeconds: parseInt(
    process.env.PIN_MAX_LOCKOUT_SECONDS || '3600',
    10,
  ),
  /**
   * Payment token (QR / NFC) HMAC: unified secret, or split per channel.
   * Production: set `QR_NFC_HMAC_SECRET`, or both `QR_SIGNING_SECRET` and `NFC_SIGNING_SECRET` (must differ).
   * Never use JWT signing material as the long-term payment MAC in production.
   */
  resolvePaymentHmacSecrets(): { qr: string; nfc: string } {
    const unified = process.env.QR_NFC_HMAC_SECRET?.trim();
    const qrOnly = process.env.QR_SIGNING_SECRET?.trim();
    const nfcOnly = process.env.NFC_SIGNING_SECRET?.trim();
    if (process.env.NODE_ENV === 'production') {
      if (unified && !qrOnly && !nfcOnly) {
        return { qr: unified, nfc: unified };
      }
      if (qrOnly && nfcOnly) {
        if (qrOnly === nfcOnly) {
          throw new Error(
            'QR_SIGNING_SECRET and NFC_SIGNING_SECRET must not match in production — use distinct key material per surface.',
          );
        }
        return { qr: qrOnly, nfc: nfcOnly };
      }
      throw new Error(
        'Production payment signing: set QR_NFC_HMAC_SECRET, or both QR_SIGNING_SECRET and NFC_SIGNING_SECRET.',
      );
    }
    const fallback =
      unified || qrOnly || nfcOnly || process.env.JWT_SECRET || DEV_ONLY_SECRET;
    return { qr: qrOnly || fallback, nfc: nfcOnly || fallback };
  },
  /** @deprecated Prefer resolvePaymentHmacSecrets() or qrSigningSecret / nfcSigningSecret per surface. */
  get qrNfcHmacSecret(): string {
    return this.resolvePaymentHmacSecrets().qr;
  },
  get qrSigningSecret(): string {
    return this.resolvePaymentHmacSecrets().qr;
  },
  get nfcSigningSecret(): string {
    return this.resolvePaymentHmacSecrets().nfc;
  },
  /**
   * IN_FLIGHT idempotency rows older than this may be reclaimed after a crash (minutes).
   * Long-running PSP flows should raise this (or lower after provider callback reliability improves).
   */
  moneyIdempotencyStaleInFlightMinutes: parseInt(
    process.env.MONEY_IDEMPOTENCY_STALE_IN_FLIGHT_MINUTES || '15',
    10,
  ),
  /** Bump when cached `response_json` shape changes so ops can filter replays. */
  moneyIdempotencyResponseContractVersion: parseInt(
    process.env.MONEY_IDEMPOTENCY_RESPONSE_CONTRACT_VERSION || '1',
    10,
  ),
  /**
   * If true, server errors delete the idempotency row (unsafe with external PSPs). Default false.
   */
  get idempotencyDeleteRowOnServerError(): boolean {
    return process.env.IDEMPOTENCY_DELETE_ROW_ON_SERVER_ERROR === 'true';
  },
  /**
   * Basis points (1/100th of a percent) withheld on QR/NFC merchant taps; remainder credits merchant.
   */
  qrMerchantFeeBps: parseInt(process.env.QR_MERCHANT_FEE_BPS || '0', 10),
  /** When false, top-up/withdrawal with a non-mock EMI_PROVIDER_TYPE is refused. */
  get realPaySettlementEnabled(): boolean {
    return process.env.NEXA_ENABLE_REAL_PAY_SETTLEMENT === 'true';
  },
};

/** Nexa Go pricing and settlement config */
export const goConfig = {
  /** UUID of the Nexa Go platform wallet (commission/booking fee). If unset, the FEES system ledger account is used. */
  platformWalletId: process.env.GO_PLATFORM_WALLET_ID?.trim() || null,
  /** Pricing config cache TTL in seconds. Default 300 (5 min). */
  pricingCacheTtlSeconds: parseInt(
    process.env.GO_PRICING_CACHE_TTL_SECONDS || '300',
    10,
  ),
  /** Notify driver when passenger cancels. */
  cancellationNotifyDriverOnPassengerCancel:
    process.env.GO_CANCELLATION_NOTIFY_DRIVER_ON_PASSENGER_CANCEL !== 'false',
  /** Auto-suspend driver after this many cancellations. */
  autoSuspendDriverCancellationThreshold: parseInt(
    process.env.GO_AUTO_SUSPEND_DRIVER_CANCELLATION_THRESHOLD || '5',
    10,
  ),
};

export const sumsubConfig = {
  appToken: process.env.SUMSUB_APP_TOKEN || '',
  secretKey: process.env.SUMSUB_SECRET_KEY || '',
  baseUrl: process.env.SUMSUB_BASE_URL || 'https://api.sumsub.com',
  levelName: process.env.SUMSUB_LEVEL_NAME || 'basic-kyc-level',
  tokenTtlSeconds: parseInt(process.env.SUMSUB_TOKEN_TTL_SECONDS || '600', 10),
  // Dedicated webhook secret only — do not fall back to SUMSUB_SECRET_KEY
  // (console webhook secret ≠ API secret; fallback caused production 400s).
  webhookSecret: (process.env.SUMSUB_WEBHOOK_SECRET || '').trim(),
  /**
   * sandbox | live — ops credential environment. Same Sumsub API host;
   * production boot requires SUMSUB_MODE=live (see assertSumsubModePolicy).
   */
  get mode(): 'sandbox' | 'live' {
    const raw = (process.env.SUMSUB_MODE ?? '').trim().toLowerCase();
    if (raw === 'live' || raw === 'sandbox') return raw;
    return (process.env.NEXA_ENV ?? '').trim().toLowerCase() === 'production'
      ? 'live'
      : 'sandbox';
  },
};

import { createParamDecorator, ExecutionContext } from '@nestjs/common';

export const CurrentUser = createParamDecorator(
  (data: unknown, ctx: ExecutionContext) => {
    const request = ctx.switchToHttp().getRequest();
    return request.user;
  },
);

import { Injectable, Logger } from '@nestjs/common';
import {
  createEventBusPublisher,
  EventValidationError,
  type EventBusPublisher,
} from '@nexa/event-bus';

@Injectable()
export class DomainEventsService {
  private readonly logger = new Logger(DomainEventsService.name);
  private readonly publisher: EventBusPublisher;

  constructor() {
    this.publisher = createEventBusPublisher();
  }

  /**
   * Publish a domain event (use EVENTS.* registry names).
   * Invalid events are REJECTED and logged as errors — never silently published.
   * Transport failures are absorbed (event bus has its own buffering/retry).
   */
  publish<T extends Record<string, unknown>>(
    type: string,
    source: string,
    payload: T,
  ) {
    return this.publisher
      .publish(type, source, payload)
      .catch((err: unknown) => {
        if (err instanceof EventValidationError) {
          this.logger.error(
            `Rejected invalid event "${err.eventType}": ${err.issues.join('; ')}`,
          );
        } else {
          this.logger.warn(
            `Event publish transport failure for "${type}": ${err instanceof Error ? err.message : err}`,
          );
        }
        return undefined;
      });
  }
}

import {
  ExceptionFilter,
  Catch,
  ArgumentsHost,
  HttpException,
  HttpStatus,
  Inject,
  Optional,
} from '@nestjs/common';
import { Request, Response } from 'express';
import type { AlertingService, ErrorMonitoringService } from '@nexa/telemetry';
import { ObsEvents } from '@nexa/telemetry';
import { noteApiError } from '../security/security-traffic';
import {
  ALERTING,
  ERROR_MONITORING,
} from '../observability/observability.tokens';

/** Standard error envelope (opt-in via x-api-envelope: 1) */
export interface ApiErrorEnvelope {
  data: null;
  meta?: { requestId?: string };
  error: {
    code: string;
    message: string;
    details?: unknown;
  };
}

function wantsEnvelope(req: Request): boolean {
  const raw = req.headers['x-api-envelope'];
  if (raw === undefined || raw === null) return false;
  const value = Array.isArray(raw) ? raw[0] : raw;
  const s = typeof value === 'string' ? value.trim() : String(value).trim();
  return s === '1' || s.toLowerCase() === 'true';
}

@Catch()
export class HttpExceptionFilter implements ExceptionFilter {
  constructor(
    @Optional()
    @Inject(ERROR_MONITORING)
    private readonly monitoring?: ErrorMonitoringService,
    @Optional()
    @Inject(ALERTING)
    private readonly alerting?: AlertingService,
  ) {}

  catch(exception: unknown, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse<Response>();
    const request = ctx.getRequest<Request & { requestId?: string }>();

    const isHttp = exception instanceof HttpException;
    const status = isHttp
      ? exception.getStatus()
      : HttpStatus.INTERNAL_SERVER_ERROR;
    const res = isHttp ? exception.getResponse() : null;
    const message =
      typeof res === 'object' && res && 'message' in res
        ? (res as { message?: string | string[] }).message
        : exception instanceof Error
          ? exception.message
          : 'Internal error';
    const messageStr = Array.isArray(message)
      ? message.join(', ')
      : String(message);
    const code =
      typeof res === 'object' && res && 'error' in res
        ? String((res as { error?: string }).error ?? 'HTTP_ERROR')
        : isHttp
          ? 'HTTP_ERROR'
          : 'INTERNAL_ERROR';
    const details =
      typeof res === 'object' &&
      res &&
      'message' in res &&
      Array.isArray((res as { message?: string[] }).message)
        ? (res as { message: string[] }).message
        : undefined;
    const requestId = request.requestId;

    if (status >= 500 || status === 401 || status === 403 || status === 429) {
      noteApiError(request, status, messageStr);
    }

    if (status >= 500) {
      this.monitoring?.captureException(exception, {
        event: ObsEvents.HTTP_5XX,
        path: request.url,
        status,
        request_id: requestId,
      });
      void this.alerting?.alert({
        key: ObsEvents.HTTP_5XX,
        severity: 'P1',
        message: `HTTP ${status} on ${request.method} ${request.path}`,
        fingerprint: `http5xx:${request.method}:${request.route?.path ?? request.path}`,
        context: { status, path: request.path, request_id: requestId },
      });
    }

    if (wantsEnvelope(request)) {
      const body: ApiErrorEnvelope = {
        data: null,
        meta: { requestId: requestId ?? '' },
        error: {
          code,
          message: messageStr,
          ...(details && { details }),
        },
      };
      response.status(status).json(body);
      return;
    }

    const legacyBody: Record<string, unknown> = {
      statusCode: status,
      timestamp: new Date().toISOString(),
      path: request.url,
      message: messageStr,
    };
    if (typeof res === 'object' && res && 'error' in res) {
      legacyBody.code = (res as { error?: string }).error;
    }
    response.status(status).json(legacyBody);
  }
}

import {
  CanActivate,
  ExecutionContext,
  ForbiddenException,
  Injectable,
  Optional,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ACCOUNT_TYPES_KEY } from '../decorators/account-type.decorator';
import type { AccountType } from '../../modules/users/entities/user.entity';
import { UsersService } from '../../modules/users/users.service';

@Injectable()
export class AccountTypeGuard implements CanActivate {
  constructor(
    private reflector: Reflector,
    @Optional() private usersService?: UsersService,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const allowed = this.reflector.getAllAndOverride<AccountType[]>(
      ACCOUNT_TYPES_KEY,
      [context.getHandler(), context.getClass()],
    );
    if (!allowed?.length) return true;

    const request = context.switchToHttp().getRequest();
    let accountType = request.user?.account_type as AccountType | undefined;
    let userId = request.user?.userId;

    // OTP/identity session tokens lack account_type - resolve to real user when UsersService is available
    if (
      !accountType &&
      (request.user?.type === 'otp_session' ||
        request.user?.type === 'identity_session') &&
      request.user?.phone_number &&
      this.usersService
    ) {
      const body = request.body || {};
      const resolvedUser = await this.usersService.findOrCreateForKyc(
        request.user.phone_number,
        body.full_name,
        body.nationality,
      );
      userId = resolvedUser.id;
      accountType = 'CONSUMER';
      request.user = {
        ...request.user,
        userId,
        account_type: accountType,
      };
    }

    if (!userId) {
      throw new ForbiddenException('User not authenticated');
    }
    if (!accountType) {
      throw new ForbiddenException('JWT missing account_type');
    }
    if (!allowed.includes(accountType)) {
      throw new ForbiddenException(
        `This endpoint requires account type: ${allowed.join(' or ')}. Your account is ${accountType}.`,
      );
    }
    return true;
  }
}

import {
  ExecutionContext,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { AuthGuard } from '@nestjs/passport';
import { IS_PUBLIC_KEY } from '../decorators/public.decorator';

@Injectable()
export class JwtAuthGuard extends AuthGuard('jwt') {
  constructor(private reflector: Reflector) {
    super();
  }

  canActivate(context: ExecutionContext) {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    const request = context.switchToHttp().getRequest();
    const authHeader = request.headers.authorization;

    if (isPublic) {
      return true;
    }

    if (!authHeader) {
      throw new UnauthorizedException('No authorization token provided');
    }

    if (!authHeader.startsWith('Bearer ')) {
      throw new UnauthorizedException('Invalid authorization header format');
    }

    return super.canActivate(context);
  }

  handleRequest(err: any, user: any, _info: any) {
    if (err || !user) {
      const message =
        err?.message ||
        (err?.name === 'TokenExpiredError'
          ? 'Token expired'
          : err?.name === 'JsonWebTokenError'
            ? 'Invalid token'
            : 'Invalid or expired token');
      throw err && err.statusCode ? err : new UnauthorizedException(message);
    }
    return user;
  }
}

import {
  CanActivate,
  ExecutionContext,
  Injectable,
  NotFoundException,
  UnauthorizedException,
} from '@nestjs/common';
import { UsersService } from '../../modules/users/users.service';

/**
 * Resolves OTP session tokens to real user IDs for registration flow.
 * When request.user has type 'otp_session' or 'identity_session':
 * - KYC routes (submit, upload): creates user if not exists.
 * - Consent routes: ensures CONSUMER user exists (same as post-OTP shell) so consents can persist.
 * - Other routes: only finds existing user; fails if none (except GET /users/me → pendingRegistration).
 */
@Injectable()
export class OtpSessionResolverGuard implements CanActivate {
  constructor(private readonly usersService: UsersService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest();
    const user = request.user;

    if (
      !user?.type ||
      (user.type !== 'otp_session' && user.type !== 'identity_session')
    ) {
      return true;
    }

    const path = (request.url || request.path || '').split('?')[0];
    const isKycRoute =
      path.includes('/kyc/submit') ||
      path.includes('/kyc/upload/document') ||
      path.includes('/kyc/upload/selfie') ||
      path.includes('/kyc/sumsub/token') ||
      path.includes('/kyc/sumsub/access-token');
    const isGetMe = path.includes('/users/me') && path.endsWith('/me');
    // Consent APIs need a real user row for user_consents. Match verifyOtp behaviour:
    // create CONSUMER shell if missing (same as findOrCreateForKyc used after OTP).
    const isConsentRoute =
      path.includes('/me/consents/current') ||
      path.includes('/me/consents/accept-mandatory') ||
      path.includes('/me/consents/marketing');

    const phoneNumber = user.phone_number as string | undefined;
    if (!phoneNumber?.trim()) {
      if (isConsentRoute || isKycRoute) {
        throw new UnauthorizedException(
          'Phone number missing from session token; obtain a new OTP session.',
        );
      }
      return true;
    }

    const body = request.body || {};
    const fullName = body.full_name as string | undefined;
    const nationality = body.nationality as string | undefined;

    const resolvedUser = isKycRoute
      ? await this.usersService.findOrCreateForKyc(
          phoneNumber,
          fullName,
          nationality,
        )
      : isConsentRoute
        ? ((await this.usersService.findForKyc(phoneNumber)) ??
          (await this.usersService.findOrCreateForKyc(phoneNumber)))
        : await this.usersService.findForKyc(phoneNumber);

    if (!resolvedUser) {
      if (isGetMe) {
        request.user = {
          ...user,
          userId: '',
          account_type: 'CONSUMER',
          pendingRegistration: true,
        };
        return true;
      }
      throw new NotFoundException('Complete KYC first to create your account');
    }

    request.user = {
      ...user,
      userId: resolvedUser.id,
      account_type: 'CONSUMER',
    };

    return true;
  }
}

import {
  CanActivate,
  ExecutionContext,
  ForbiddenException,
  Injectable,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ROLES_KEY } from '../decorators/roles.decorator';
import { AuthzVersionService } from '../../modules/auth/authz-version.service';

function jwtRoles(user: { roles?: string[]; role?: string }): string[] {
  if (Array.isArray(user?.roles) && user.roles.length > 0) {
    return user.roles.map(String);
  }
  if (user?.role) return [String(user.role)];
  return [];
}

function isStaffRole(role: string): boolean {
  return role === 'ADMIN' || role === 'SUPPORT_AGENT';
}

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(
    private reflector: Reflector,
    private readonly authzVersions: AuthzVersionService,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const requiredRoles = this.reflector.getAllAndOverride<string[]>(
      ROLES_KEY,
      [context.getHandler(), context.getClass()],
    );

    if (!requiredRoles || requiredRoles.length === 0) {
      return true;
    }

    const request = context.switchToHttp().getRequest();
    const user = request.user;

    if (!user) {
      throw new ForbiddenException('User not authenticated');
    }

    const userRoles = jwtRoles(user);
    const hasRole = requiredRoles.some((role) => userRoles.includes(role));

    if (!hasRole) {
      throw new ForbiddenException(
        `Insufficient permissions. Required roles: ${requiredRoles.join(', ')}`,
      );
    }

    const staffContext =
      requiredRoles.some(isStaffRole) || userRoles.some(isStaffRole);
    if (staffContext) {
      const state = await this.authzVersions.getAuthzState(user.userId);
      if (state.account_type !== 'ADMIN') {
        throw new ForbiddenException('Administrator privilege revoked');
      }
      if (state.status === 'FROZEN') {
        throw new ForbiddenException('Administrator privilege revoked');
      }
      const tokenVersion = Number(user.authz_version ?? user.av);
      if (
        !Number.isFinite(tokenVersion) ||
        tokenVersion !== state.authz_version
      ) {
        throw new ForbiddenException('Administrator privilege revoked');
      }
    }

    return true;
  }
}

import { ExecutionContext, Injectable } from '@nestjs/common';
import { ThrottlerGuard, ThrottlerException } from '@nestjs/throttler';
import { noteRateLimited } from '../security/security-traffic';

/**
 * Global throttle: prefer rate-limit by user id when authenticated, else by IP.
 */
@Injectable()
export class ThrottlerKeyGuard extends ThrottlerGuard {
  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest();
    const path = (request.url || request.path || '').split('?')[0];
    if (path.includes('/users/me') && request.method === 'GET') return true;
    try {
      return await super.canActivate(context);
    } catch (err) {
      if (err instanceof ThrottlerException) {
        noteRateLimited(request);
      }
      throw err;
    }
  }

  protected async getTracker(req: Record<string, unknown>): Promise<string> {
    const user = req.user as { sub?: string; userId?: string } | undefined;
    const id = user?.userId || user?.sub;
    if (id && typeof id === 'string') {
      return `user:${id}`;
    }
    const ip =
      (req as { ip?: string }).ip ||
      (req.connection as { remoteAddress?: string } | undefined)
        ?.remoteAddress ||
      (req.headers as Record<string, string | string[] | undefined>)?.[
        'x-forwarded-for'
      ];
    const ipStr = Array.isArray(ip)
      ? ip[0]
      : typeof ip === 'string'
        ? ip.split(',')[0].trim()
        : '';
    return `ip:${ipStr || '0.0.0.0'}`;
  }
}

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/operators';
import { MetricsService } from './metrics.service';

@Injectable()
export class MetricsInterceptor implements NestInterceptor {
  constructor(private readonly metricsService: MetricsService) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const res = context.switchToHttp().getResponse();
    this.metricsService.incrementTotal();
    return next.handle().pipe(
      tap({
        next: () => {
          const code = res.statusCode as number;
          if (code >= 500) this.metricsService.increment5xx();
          else if (code >= 400) this.metricsService.increment4xx();
        },
        error: () => {
          const code = res.statusCode as number;
          if (code >= 500) this.metricsService.increment5xx();
          else if (code >= 400) this.metricsService.increment4xx();
        },
      }),
    );
  }
}

import { Injectable, NestMiddleware } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import type { NextFunction, Request, Response } from 'express';
import { Repository } from 'typeorm';
import { createHash } from 'crypto';
import { User } from '../../modules/users/entities/user.entity';
import { AuditLog } from '../../modules/audit/entities/audit-log.entity';
import { RiskAlert } from '../../modules/admin/entities/risk-alert.entity';
import { SecurityEventsService } from '../../modules/security-events/security-events.service';

export type RiskAuthLevel = 'LOW' | 'MEDIUM' | 'HIGH';

export interface RiskAuthAssessment {
  user_id: string | null;
  risk_score: number;
  level: RiskAuthLevel;
  reason_codes: string[];
  context: {
    ip: string;
    country: string | null;
    device_id: string | null;
    device_fingerprint: string;
    user_agent: string | null;
  };
}

type RiskAuthRequest = Request & { risk_auth?: RiskAuthAssessment };

@Injectable()
export class RiskAuthMiddleware implements NestMiddleware {
  constructor(
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
    @InjectRepository(AuditLog)
    private readonly auditRepository: Repository<AuditLog>,
    @InjectRepository(RiskAlert)
    private readonly riskAlertRepository: Repository<RiskAlert>,
    private readonly securityEventsService: SecurityEventsService,
  ) {}

  private get mediumThreshold(): number {
    return Number(process.env.RISK_AUTH_MEDIUM_THRESHOLD ?? 50);
  }

  private get highThreshold(): number {
    return Number(process.env.RISK_AUTH_HIGH_THRESHOLD ?? 80);
  }

  async use(req: RiskAuthRequest, _res: Response, next: NextFunction) {
    const assessment = await this.buildAssessment(req);
    req.risk_auth = assessment;
    if (assessment.reason_codes.length > 0) {
      await this.securityEventsService.logEvent({
        user_id: assessment.user_id,
        event_type: 'DEVICE_ANOMALY',
        metadata: {
          risk_score: assessment.risk_score,
          risk_level: assessment.level,
          reason_codes: assessment.reason_codes,
          country: assessment.context.country,
          device_fingerprint: assessment.context.device_fingerprint,
        },
        ip_address: assessment.context.ip,
        device_id: assessment.context.device_id,
      });
    }
    if (assessment.level === 'HIGH' && assessment.user_id) {
      await this.riskAlertRepository.save({
        type: 'ADAPTIVE_AUTH_HIGH_RISK',
        severity: 'HIGH',
        user_id: assessment.user_id,
        transaction_id: null,
        description: `High-risk adaptive auth event: ${assessment.reason_codes.join(', ')}`,
        risk_score: assessment.risk_score,
        status: 'OPEN',
      });
    }
    next();
  }

  private async buildAssessment(
    req: RiskAuthRequest,
  ): Promise<RiskAuthAssessment> {
    const userId = await this.resolveTargetUserId(req);
    const context = this.extractContext(req);
    if (!userId) {
      return {
        user_id: null,
        risk_score: 0,
        level: 'LOW',
        reason_codes: [],
        context,
      };
    }

    const lastLoginAudit = await this.auditRepository.findOne({
      where: { user_id: userId, action: 'LOGIN_SUCCESS' },
      order: { created_at: 'DESC' },
    });
    const previous = this.parsePreviousContext(lastLoginAudit?.metadata);

    let score = 0;
    const reasons: string[] = [];

    if (previous.ip && previous.ip !== context.ip) {
      score += 30;
      reasons.push('IP_CHANGED');
    }
    if (
      previous.country &&
      context.country &&
      previous.country.toUpperCase() !== context.country.toUpperCase()
    ) {
      score += 35;
      reasons.push('GEO_ANOMALY_COUNTRY_CHANGED');
    }
    if (
      previous.device_fingerprint &&
      previous.device_fingerprint !== context.device_fingerprint
    ) {
      score += 40;
      reasons.push('DEVICE_FINGERPRINT_MISMATCH');
    }

    const level: RiskAuthLevel =
      score >= this.highThreshold
        ? 'HIGH'
        : score >= this.mediumThreshold
          ? 'MEDIUM'
          : 'LOW';

    return {
      user_id: userId,
      risk_score: score,
      level,
      reason_codes: reasons,
      context,
    };
  }

  private async resolveTargetUserId(
    req: RiskAuthRequest,
  ): Promise<string | null> {
    const jwtUserId = (req as Request & { user?: { userId?: string } }).user
      ?.userId;
    if (jwtUserId) return jwtUserId;

    const phone = this.getString(req.body?.phone_number);
    if (!phone) return null;
    const accountType = this.getString(req.body?.account_type) ?? 'CONSUMER';
    const user = await this.userRepository.findOne({
      where: { phone_number: phone, account_type: accountType as any },
      select: ['id'],
    });
    return user?.id ?? null;
  }

  private extractContext(req: Request): RiskAuthAssessment['context'] {
    const ip =
      (req.ip || '').trim() ||
      ((req.connection as { remoteAddress?: string } | undefined)
        ?.remoteAddress ??
        '') ||
      '0.0.0.0';
    const country =
      this.getString(req.headers['cf-ipcountry']) ||
      this.getString(req.headers['x-country-code']) ||
      this.getString(req.headers['x-geo-country']) ||
      null;
    const deviceId = this.getString(req.headers['x-device-id']) ?? null;
    const userAgent = this.getString(req.headers['user-agent']) ?? null;
    const explicitFingerprint = this.getString(
      req.headers['x-device-fingerprint'],
    );
    const fingerprintSource =
      explicitFingerprint || `${deviceId || ''}|${userAgent || ''}`;
    const deviceFingerprint = createHash('sha256')
      .update(fingerprintSource)
      .digest('hex');
    return {
      ip,
      country,
      device_id: deviceId,
      device_fingerprint: deviceFingerprint,
      user_agent: userAgent,
    };
  }

  private parsePreviousContext(
    metadata: Record<string, unknown> | undefined | null,
  ): { ip?: string; country?: string; device_fingerprint?: string } {
    if (!metadata || typeof metadata !== 'object') return {};
    return {
      ip: this.getString(metadata.ip),
      country: this.getString(metadata.country),
      device_fingerprint: this.getString(metadata.device_fingerprint),
    };
  }

  private getString(value: unknown): string | undefined {
    return typeof value === 'string' && value.trim() ? value.trim() : undefined;
  }
}

