/**
 * Raw query builders bypass the entity `piiTransformer`, so encrypted columns
 * arrive as `enc:v1:…` blobs. Decrypt for the admin DTO; never fail the request.
 */
function decryptPiiSafe(value: unknown): string | null {
  if (typeof value !== 'string' || !value) return null;
  try {
    return decryptPii(value);
  } catch {
    return null;
  }
}

interface RequestUser {
  userId?: string;
  email?: string;
}

function getIpAndAgent(req?: Request): {
  ipAddress?: string;
  deviceId?: string;
} {
  if (!req) return {};
  const ip =
    (req as Request & { ip?: string }).ip ||
    (req.connection as { remoteAddress?: string } | undefined)?.remoteAddress ||
    (req.headers?.['x-forwarded-for'] as string)?.split(',')[0]?.trim();
  const ua = req.headers?.['user-agent'];
  return {
    ipAddress: ip ?? undefined,
    deviceId: ua ? String(ua).slice(0, 100) : undefined,
  };
}

const API_PREFIX = appConfig.apiPrefix;

/** Schemes we treat as absolute URLs (return as-is; no /kyc/files/ prefix). */
const ABSOLUTE_URL_SCHEMES = ['http://', 'https://', 's3://', 'gs://'];

function isAbsoluteUrl(value: string): boolean {
  const lower = value.toLowerCase();
  return ABSOLUTE_URL_SCHEMES.some((scheme) => lower.startsWith(scheme));
}

function fileUrlFromPath(
  userId: string,
  relativePath: string | null | undefined,
): string | null {
  if (!relativePath || typeof relativePath !== 'string') return null;
  if (isAbsoluteUrl(relativePath)) {
    return relativePath;
  }
  const filename = relativePath.includes('/')
    ? relativePath.split('/').pop()!
    : relativePath;
  return `/${API_PREFIX}/kyc/files/${userId}/${filename}`;
}

@Injectable()
export class AdminKycService {
  constructor(
    @InjectRepository(KycProfile)
    private readonly kycRepository: Repository<KycProfile>,
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
    private readonly auditService: AdminAuditService,
    private readonly kycReuseService: KycReuseService,
    private readonly snapshotService: IdentitySnapshotService,
    private readonly domainEvents: DomainEventsService,
    private readonly complianceService: ComplianceService,
  ) {}

  /**
   * Admin-triggered re-pull of the Sumsub applicant for a case. Backfills empty
   * identity fields (name, DOB, nationality, document type/country/number) via
   * the same path the webhook uses, then returns the refreshed case DTO.
   */
  async resyncFromSumsub(id: string, adminUser?: RequestUser, req?: Request) {
    const kyc = await this.kycRepository.findOne({ where: { id } });
    if (!kyc) {
      throw new NotFoundException('KYC case not found');
    }
    if ((kyc.provider ?? '').toUpperCase() !== 'SUMSUB') {
      throw new BadRequestException(
        'This case was not verified through Sumsub',
      );
    }
    const source = (kyc.source ?? 'PAY').toUpperCase();
    const sync = await this.complianceService.syncSumsubDossier(
      kyc.user_id,
      source,
    );

    const { ipAddress, deviceId } = getIpAndAgent(req);
    await this.auditService.logAction({
      action: 'KYC_SUMSUB_RESYNC',
      entityType: 'kyc',
      entityId: kyc.id,
      userId: kyc.user_id,
      adminUser,
      ipAddress,
      deviceId,
    });
    await this.snapshotService.invalidate(kyc.user_id);

    return {
      sync,
      case: await this.getCase(id),
    };
  }

  /** DEV only: returns KYC profile info for debugging. 404 in production. */
  async getDebugUser(userId: string) {
    if (process.env.NODE_ENV === 'production') {
      throw new NotFoundException('Not found');
    }
    const kyc = await this.kycRepository.findOne({
      where: { user_id: userId },
      select: ['id', 'status', 'source', 'created_at'],
    });
    if (!kyc) {
      return {
        hasKycProfile: false,
        status: null,
        source: null,
        created_at: null,
      };
    }
    return {
      hasKycProfile: true,
      status: kyc.status,
      source: kyc.source ?? 'NULL',
      created_at: kyc.created_at,
    };
  }

  async getQueue(query: AdminKycQueryDto) {
    const srcRaw = (query.source ?? 'ALL').trim().toUpperCase();
    /** Unified KYC: ALL = all sources; otherwise filter by PAY | GO | STAYS */
    const src = srcRaw === '' ? 'ALL' : srcRaw;
    if (src !== 'ALL' && !['PAY', 'GO', 'STAYS'].includes(src)) {
      throw new BadRequestException(
        'source must be one of: PAY, GO, STAYS, ALL (or omit for unified)',
      );
    }

    const qb = this.kycRepository
      .createQueryBuilder('k')
      .leftJoin(User, 'u', 'u.id = k.user_id')
      .select([
        'k.id as id',
        'k.user_id as user_id',
        'u.phone_number as user_phone',
        'u.full_name as user_name',
        'k.status as status',
        'k.level as level',
        'k.provider as provider',
        'k.created_at as submitted_at',
        'k.reviewed_at as reviewed_at',
        'k.reviewed_by as reviewed_by',
        'k.last_webhook_event_type as last_webhook_event_type',
        'k.last_webhook_received_at as last_webhook_received_at',
        'k.rejection_reason as rejection_reason',
        'k.documents as documents',
        'k.aml_screening as aml_screening',
        'k.id_document_url as id_document_url',
        'k.selfie_url as selfie_url',
        'k.document_front_url as document_front_url',
        'k.document_back_url as document_back_url',
        'k.document_type as document_type',
        'k.document_country as document_country',
        'k.full_name as full_name',
        'k.email as email',
        'k.date_of_birth as date_of_birth',
        'k.nationality as nationality',
        'k.national_id_number as national_id_number',
        'k.national_id_number_extracted as national_id_number_extracted',
        'k.source as source',
        'u.account_type as account_type',
        'u.city as user_city',
        'u.email as user_email',
      ])
      // Host profiles live in the stays DB — approximate via KYC source.
      .addSelect(`(k.source = 'STAYS')`, 'is_host')
      .orderBy('k.created_at', 'DESC');

    if (query.status && query.status !== 'all') {
      const statusVal = query.status.trim().toUpperCase();
      // KYC approve writes VERIFIED; treat APPROVED and VERIFIED as equivalent for filtering
      if (statusVal === 'APPROVED') {
        qb.andWhere('k.status IN (:...statuses)', {
          statuses: ['APPROVED', 'VERIFIED'],
        });
      } else {
        qb.andWhere('k.status = :status', { status: statusVal });
      }
    }

    {
      if (src === 'ALL') {
        // Unified: all KYC across ecosystem (PAY=null/PAY, GO, STAYS)
        qb.andWhere(
          '(k.source IS NULL OR k.source = :pay OR k.source = :go OR k.source = :stays)',
          { pay: 'PAY', go: 'GO', stays: 'STAYS' },
        );
      } else if (src === 'PAY') {
        qb.andWhere('(k.source IS NULL OR k.source = :source)', {
          source: 'PAY',
        });
      } else if (src === 'GO') {
        qb.andWhere('k.source = :source', { source: 'GO' });
      } else if (src === 'STAYS') {
        qb.andWhere('k.source = :source', { source: 'STAYS' });
      }
    }

    if (query.account_type && query.account_type.trim() !== '') {
      const act = query.account_type.trim().toUpperCase();
      const goTypes = ['CONSUMER', 'DRIVER', 'COURIER', 'MERCHANT'];
      const payTypes = ['CONSUMER', 'MERCHANT'];
      if ((src === 'ALL' || src === 'GO') && goTypes.includes(act)) {
        qb.andWhere('u.account_type = :accountType', { accountType: act });
      } else if ((src === 'PAY' || src === 'STAYS') && payTypes.includes(act)) {
        qb.andWhere('u.account_type = :accountType', { accountType: act });
      }
    }

    if (
      query.stays_role &&
      query.stays_role.trim() !== '' &&
      (src === 'STAYS' || src === 'ALL')
    ) {
      const role = query.stays_role.trim().toUpperCase();
      if (role === 'HOST') {
        qb.andWhere(`k.source = 'STAYS'`);
      } else if (role === 'USER') {
        qb.andWhere(`(k.source IS NULL OR k.source <> 'STAYS')`);
      }
    }

    if (query.search && query.search.trim() !== '') {
      const term = query.search.trim();
      const uuidRegex =
        /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
      if (uuidRegex.test(term)) {
        qb.andWhere('k.user_id = :userId', { userId: term });
      } else {
        qb.andWhere("u.phone_number ILIKE :phone ESCAPE '\\'", {
          phone: `%${term.replace(/\\/g, '\\\\').replace(/[%_]/g, '\\$&')}%`,
        });
      }
    }

    const docCat = (query.document_category ?? '').trim().toLowerCase();
    if (docCat && docCat !== 'all') {
      if (docCat === 'national_id' || docCat === 'cin' || docCat === 'cni') {
        qb.andWhere(
          "(k.document_type ILIKE '%National Identity%' OR k.document_type ILIKE '%CNIE%' OR k.document_type ILIKE '%CIN%' OR k.document_type ILIKE '%Carte nationale%')",
        );
      } else if (docCat === 'passport') {
        qb.andWhere("k.document_type ILIKE '%Passport%'");
      } else if (
        docCat === 'driver_license' ||
        docCat === 'license' ||
        docCat === 'driving'
      ) {
        qb.andWhere(
          "(k.document_type ILIKE '%Driver%' OR k.document_type ILIKE '%Driving%' OR k.document_type ILIKE '%Permis%')",
        );
      }
    }

    const page = Math.max(1, Number(query.page) || 1);
    const limit = Math.min(100, Math.max(1, Number(query.limit) || 50));
    const skip = (page - 1) * limit;
    qb.skip(skip).take(limit);

    const rows = await qb.getRawMany();
    return rows.map((row) => this.toAdminKycDto(row));
  }

  private toAdminKycDto(row: Record<string, unknown>) {
    const userId = row.user_id as string;
    const documentFrontPath = (row.document_front_url ??
      row.id_document_url) as string | null | undefined;
    const documentBackPath = row.document_back_url as string | null | undefined;
    const selfiePath = row.selfie_url as string | null | undefined;

    const kycFullName = (row.full_name as string | null | undefined) ?? null;
    const userFullName = (row.user_name as string | null | undefined) ?? null;
    const formFullName = kycFullName ?? userFullName;
    const kycEmail = (row.email as string | null | undefined) ?? null;
    const userEmail = (row.user_email as string | null | undefined) ?? null;
    const mergedEmail = kycEmail ?? userEmail;
    const userCity = (row.user_city as string | null | undefined) ?? null;

    const documentFileUrlFront = fileUrlFromPath(userId, documentFrontPath);
    const documentFileUrlBack = fileUrlFromPath(userId, documentBackPath);
    const selfieFileUrl = fileUrlFromPath(userId, selfiePath);
    const nationalIdNumber = decryptPiiSafe(row.national_id_number);
    const nationalIdNumberExtracted = decryptPiiSafe(
      row.national_id_number_extracted,
    );

    return {
      userId,
      user_id: userId, // frontend compatibility (KycQueue uses user_id for approve)
      phoneNumber: row.user_phone ?? null,
      /** Flat fields for admin dashboards (avoid relying only on nested kycProfile). */
      document_type: row.document_type ?? null,
      document_country: row.document_country ?? null,
      national_id_number: nationalIdNumber,
      national_id_number_extracted: nationalIdNumberExtracted,
      full_name: formFullName,
      kyc_full_name: kycFullName,
      user_full_name: userFullName,
      email: mergedEmail,
      kyc_email: kycEmail,
      user_email: userEmail,
      city: userCity,
      date_of_birth: row.date_of_birth ?? null,
      nationality: row.nationality ?? null,
      document_valid_until: row.document_valid_until ?? null,
      document_file_url_front: documentFileUrlFront,
      document_file_url_back: documentFileUrlBack,
      selfie_file_url: selfieFileUrl,
      provider_level_name: row.provider_level_name ?? null,
      provider_review_status: row.provider_review_status ?? null,
      provider_review_answer: row.provider_review_answer ?? null,
      provider_attempt_cnt: row.provider_attempt_cnt ?? null,
      provider_inspection_id: row.provider_inspection_id ?? null,
      provider_synced_at: row.provider_synced_at ?? null,
      kycProfile: {
        status: row.status ?? 'PENDING',
        document_type: row.document_type ?? null,
        document_country: row.document_country ?? null,
        document_valid_until: row.document_valid_until ?? null,
        document_front_url: documentFrontPath ?? null,
        document_back_url: documentBackPath ?? null,
        selfie_url: selfiePath ?? null,
        rejection_reason: row.rejection_reason ?? null,
        reviewed_at: row.reviewed_at ?? null,
        reviewed_by: row.reviewed_by ?? null,
        last_webhook_event_type: row.last_webhook_event_type ?? null,
        last_webhook_received_at: row.last_webhook_received_at ?? null,
        document_file_url_front: documentFileUrlFront,
        document_file_url_back: documentFileUrlBack,
        selfie_file_url: selfieFileUrl,
        full_name: kycFullName,
        email: kycEmail,
        date_of_birth: row.date_of_birth ?? null,
        nationality: row.nationality ?? null,
        national_id_number: nationalIdNumber,
        national_id_number_extracted: nationalIdNumberExtracted,
        provider_level_name: row.provider_level_name ?? null,
        provider_review_status: row.provider_review_status ?? null,
        provider_review_answer: row.provider_review_answer ?? null,
        provider_attempt_cnt: row.provider_attempt_cnt ?? null,
        provider_inspection_id: row.provider_inspection_id ?? null,
        provider_synced_at: row.provider_synced_at ?? null,
      },
      id: row.id,
      status: (row.status as string) ?? 'PENDING',
      user_phone: row.user_phone,
      user_name: row.user_name,
      level: row.level,
      provider: row.provider,
      /** Provider reference (Sumsub applicantId once reviewed) — lets admins open the applicant in the provider console. */
      reference: (row.reference as string | null | undefined) ?? null,
      submitted_at: row.submitted_at,
      last_webhook_event_type: row.last_webhook_event_type ?? null,
      last_webhook_received_at: row.last_webhook_received_at ?? null,
      documents: row.documents || {
        id_document: false,
        selfie: false,
        liveness: false,
        phone: false,
      },
      aml_screening: row.aml_screening || { status: 'PENDING', score: 0 },
      source: row.source ?? 'PAY',
      account_type: row.account_type ?? null,
      is_host: row.is_host === true || row.is_host === 'true',
    };
  }

  async getCase(id: string) {
    const qb = this.kycRepository
      .createQueryBuilder('k')
      .leftJoin(User, 'u', 'u.id = k.user_id')
      .select([
        'k.id as id',
        'k.user_id as user_id',
        'u.phone_number as user_phone',
        'u.full_name as user_name',
        'k.status as status',
        'k.level as level',
        'k.provider as provider',
        'k.reference as reference',
        'k.created_at as submitted_at',
        'k.reviewed_at as reviewed_at',
        'k.reviewed_by as reviewed_by',
        'k.last_webhook_event_type as last_webhook_event_type',
        'k.last_webhook_received_at as last_webhook_received_at',
        'k.rejection_reason as rejection_reason',
        'k.documents as documents',
        'k.aml_screening as aml_screening',
        'k.id_document_url as id_document_url',
        'k.selfie_url as selfie_url',
        'k.document_front_url as document_front_url',
        'k.document_back_url as document_back_url',
        'k.document_type as document_type',
        'k.document_country as document_country',
        'k.full_name as full_name',
        'k.email as email',
        'k.date_of_birth as date_of_birth',
        'k.nationality as nationality',
        'k.national_id_number as national_id_number',
        'k.national_id_number_extracted as national_id_number_extracted',
        'k.document_valid_until as document_valid_until',
        'k.provider_level_name as provider_level_name',
        'k.provider_review_status as provider_review_status',
        'k.provider_review_answer as provider_review_answer',
        'k.provider_attempt_cnt as provider_attempt_cnt',
        'k.provider_inspection_id as provider_inspection_id',
        'k.provider_synced_at as provider_synced_at',
        'k.source as source',
        'u.account_type as account_type',
        'u.city as user_city',
        'u.email as user_email',
      ])
      .addSelect(`(k.source = 'STAYS')`, 'is_host')
      .where('k.id = :id', { id });
    const row = await qb.getRawOne();
    if (!row) {
      throw new NotFoundException('KYC case not found');
    }
    return this.toAdminKycDto(row);
  }

  async approve(id: string, adminUser?: RequestUser, req?: Request) {
    const kyc = await this.kycRepository.findOne({ where: { id } });
    if (!kyc) {
      throw new NotFoundException('KYC case not found');
    }

    kyc.status = 'VERIFIED';
    kyc.reviewed_at = new Date();
    kyc.reviewed_by = adminUser?.email || adminUser?.userId || 'admin';
    kyc.rejection_reason = null;
    await this.kycRepository.save(kyc);

    const user = await this.userRepository.findOne({
      where: { id: kyc.user_id },
      select: ['id', 'phone_number', 'profile_locked_at'],
    });
    if (user?.phone_number) {
      try {
        await this.kycReuseService.syncFromKycApproval(user.phone_number, kyc);
      } catch (err) {
        safeLogger.info('Reusable KYC sync failed (non-fatal)', {
          userId: kyc.user_id,
          err: String((err as Error)?.message ?? err),
        });
      }
    }
    const updatePayload: { kyc_status: string; profile_locked_at?: Date } = {
      kyc_status: 'APPROVED',
    };
    if (user && !user.profile_locked_at) {
      updatePayload.profile_locked_at = new Date();
    }
    await this.userRepository.update(kyc.user_id, updatePayload);

    const { ipAddress, deviceId } = getIpAndAgent(req);
    await this.auditService.logAction({
      action: 'KYC_VERIFIED',
      entityType: 'kyc',
      entityId: kyc.id,
      userId: kyc.user_id,
      adminUser,
      ipAddress,
      deviceId,
    });

    await this.snapshotService.invalidate(kyc.user_id);
    const userRow = await this.userRepository.findOne({
      where: { id: kyc.user_id },
      select: ['id', 'unified_identity_id'],
    });
    void this.domainEvents.publish(EVENTS.KYC_UPDATED, 'identity', {
      userId: kyc.user_id,
      unifiedIdentityId: userRow?.unified_identity_id ?? '',
      kycStatus: 'VERIFIED',
      kycTier: (kyc.level ?? 'BASIC').toUpperCase(),
      kycLevel: kycTierToLevel(kyc.level),
    });

    return { success: true };
  }

  async reject(
    id: string,
    reason: string,
    adminUser?: RequestUser,
    req?: Request,
  ) {
    const kyc = await this.kycRepository.findOne({ where: { id } });
    if (!kyc) {
      throw new NotFoundException('KYC case not found');
    }

    kyc.status = 'REJECTED';
    kyc.reviewed_at = new Date();
    kyc.reviewed_by = adminUser?.email || adminUser?.userId || 'admin';
    kyc.rejection_reason = reason;
    await this.kycRepository.save(kyc);

    await this.userRepository.update(kyc.user_id, { kyc_status: 'REJECTED' });

    const { ipAddress, deviceId } = getIpAndAgent(req);
    await this.auditService.logAction({
      action: 'KYC_REJECTED',
      entityType: 'kyc',
      entityId: kyc.id,
      userId: kyc.user_id,
      metadata: { reason },
      adminUser,
      ipAddress,
      deviceId,
    });

    return { success: true };
  }

  async approveByUser(
    userId: string,
    adminUser?: RequestUser,
    req?: Request,
    expectedSource?: string,
  ) {
    const kyc = await this.kycRepository.findOne({
      where: { user_id: userId },
    });
    if (!kyc) {
      throw new NotFoundException('KYC case not found');
    }
    this.assertSourceMatch(kyc.source, expectedSource);
    return this.approve(kyc.id, adminUser, req);
  }

  async rejectByUser(
    userId: string,
    reason: string,
    adminUser?: RequestUser,
    req?: Request,
    expectedSource?: string,
  ) {
    const kyc = await this.kycRepository.findOne({
      where: { user_id: userId },
    });
    if (!kyc) {
      throw new NotFoundException('KYC case not found');
    }
    this.assertSourceMatch(kyc.source, expectedSource);
    return this.reject(kyc.id, reason, adminUser, req);
  }

  /** When expectedSource provided (PAY|GO|STAYS), verifies KYC belongs to that dashboard. */
  private assertSourceMatch(kycSource: string | null, expectedSource?: string) {
    if (!expectedSource || !['PAY', 'GO', 'STAYS'].includes(expectedSource))
      return;
    const kycSrc = (kycSource ?? 'PAY').toUpperCase();
    if (kycSrc !== expectedSource) {
      throw new ForbiddenException(
        `KYC was submitted from ${kycSrc}, not ${expectedSource}. Cannot approve from this dashboard.`,
      );
    }
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { RiskAlert } from '../entities/risk-alert.entity';
import { AdminRiskQueryDto } from '../dto/admin-risk.query.dto';
import { AdminMonitoringQueryDto } from '../dto/admin-monitoring.query.dto';
import { AppTransaction } from '../../transactions/entities/app-transaction.entity';
import { User } from '../../users/entities/user.entity';
import { AdminAuditService } from './admin-audit.service';
import { FraudEvent } from '../../fraud/entities/fraud-event.entity';
import { SarReport } from '../../compliance/entities/sar-report.entity';
import { ReconciliationIssue } from '../../reconciliation/entities/reconciliation-issue.entity';

interface RequestUser {
  userId?: string;
  email?: string;
}

@Injectable()
export class AdminRiskService {
  constructor(
    @InjectRepository(RiskAlert)
    private readonly riskRepository: Repository<RiskAlert>,
    @InjectRepository(FraudEvent)
    private readonly fraudEventRepository: Repository<FraudEvent>,
    @InjectRepository(SarReport)
    private readonly sarReportRepository: Repository<SarReport>,
    @InjectRepository(ReconciliationIssue)
    private readonly reconciliationIssueRepository: Repository<ReconciliationIssue>,
    @InjectRepository(AppTransaction)
    private readonly transactionsRepository: Repository<AppTransaction>,
    private readonly auditService: AdminAuditService,
  ) {}

  private toWindow(query: AdminMonitoringQueryDto): {
    from?: Date;
    to?: Date;
  } {
    return {
      from: query.from_date ? new Date(query.from_date) : undefined,
      to: query.to_date ? new Date(query.to_date) : undefined,
    };
  }

  private toPaging(query: AdminMonitoringQueryDto): {
    page: number;
    limit: number;
  } {
    return {
      page: query.page ?? 1,
      limit: Math.min(query.limit ?? 50, 200),
    };
  }

  private applyDateRange(
    qb: ReturnType<Repository<any>['createQueryBuilder']>,
    alias: string,
    column: string,
    query: AdminMonitoringQueryDto,
  ) {
    const { from, to } = this.toWindow(query);
    if (from) {
      qb.andWhere(`${alias}.${column} >= :fromDate`, { fromDate: from });
    }
    if (to) {
      qb.andWhere(`${alias}.${column} <= :toDate`, { toDate: to });
    }
  }

  private applyCommonFilters(
    qb: ReturnType<Repository<any>['createQueryBuilder']>,
    alias: string,
    query: AdminMonitoringQueryDto,
  ) {
    this.applyDateRange(qb, alias, 'created_at', query);
    if (query.status && query.status !== 'all') {
      qb.andWhere(`${alias}.status = :status`, { status: query.status });
    }
    if (query.user_id) {
      qb.andWhere(`${alias}.user_id = :userId`, { userId: query.user_id });
    }
    if (query.transaction_id) {
      qb.andWhere(`${alias}.transaction_id = :transactionId`, {
        transactionId: query.transaction_id,
      });
    }
  }

  async getRiskSummary(query: AdminMonitoringQueryDto) {
    const riskAlertsQb = this.riskRepository.createQueryBuilder('r');
    this.applyDateRange(riskAlertsQb, 'r', 'created_at', query);
    if (query.severity && query.severity !== 'all') {
      riskAlertsQb.andWhere('r.severity = :severity', {
        severity: query.severity,
      });
    }

    const fraudQb = this.fraudEventRepository.createQueryBuilder('f');
    this.applyDateRange(fraudQb, 'f', 'created_at', query);
    if (query.severity && query.severity !== 'all') {
      fraudQb.andWhere('f.severity = :severity', { severity: query.severity });
    }

    const sarQb = this.sarReportRepository.createQueryBuilder('s');
    this.applyDateRange(sarQb, 's', 'created_at', query);
    if (query.severity && query.severity !== 'all') {
      const [min, max] =
        query.severity === 'HIGH'
          ? [80, null]
          : query.severity === 'MEDIUM'
            ? [50, 79]
            : [0, 49];
      sarQb.andWhere('s.risk_score >= :minRisk', { minRisk: min });
      if (max != null)
        sarQb.andWhere('s.risk_score <= :maxRisk', { maxRisk: max });
    }

    const recQb = this.reconciliationIssueRepository.createQueryBuilder('ri');
    this.applyDateRange(recQb, 'ri', 'created_at', query);
    if (query.severity && query.severity !== 'all') {
      recQb.andWhere('ri.severity = :severity', { severity: query.severity });
    }

    const [
      riskAlertCount,
      openRiskAlertCount,
      fraudEventCount,
      sarCount,
      openSarCount,
      reconciliationIssueCount,
      openReconciliationCount,
    ] = await Promise.all([
      riskAlertsQb.getCount(),
      riskAlertsQb
        .clone()
        .andWhere('r.status = :status', { status: 'OPEN' })
        .getCount(),
      fraudQb.getCount(),
      sarQb.getCount(),
      sarQb
        .clone()
        .andWhere('s.status IN (:...statuses)', {
          statuses: ['OPEN', 'UNDER_REVIEW'],
        })
        .getCount(),
      recQb.getCount(),
      recQb
        .clone()
        .andWhere('ri.status = :status', { status: 'OPEN' })
        .getCount(),
    ]);

    return {
      window: {
        from_date: query.from_date ?? null,
        to_date: query.to_date ?? null,
        severity: query.severity ?? 'all',
      },
      totals: {
        risk_alerts: riskAlertCount,
        fraud_events: fraudEventCount,
        sar_reports: sarCount,
        reconciliation_issues: reconciliationIssueCount,
      },
      open: {
        risk_alerts: openRiskAlertCount,
        sar_reports: openSarCount,
        reconciliation_issues: openReconciliationCount,
      },
    };
  }

  async getFraudEvents(query: AdminMonitoringQueryDto) {
    const { page, limit } = this.toPaging(query);
    const qb = this.fraudEventRepository
      .createQueryBuilder('f')
      .orderBy('f.created_at', 'DESC')
      .skip((page - 1) * limit)
      .take(limit);
    this.applyCommonFilters(qb, 'f', query);
    if (query.severity && query.severity !== 'all') {
      qb.andWhere('f.severity = :severity', { severity: query.severity });
    }
    if (query.search) {
      qb.andWhere(
        '(f.reason_code ILIKE :search OR f.transaction_type ILIKE :search OR CAST(f.user_id AS text) ILIKE :search)',
        { search: `%${query.search}%` },
      );
    }
    const [rows, total] = await Promise.all([qb.getMany(), qb.getCount()]);
    return {
      page,
      limit,
      total,
      data: rows.map((row) => ({
        id: row.id,
        user_id: row.user_id,
        transaction_type: row.transaction_type,
        amount: Number(row.amount),
        risk_score: row.risk_score,
        reason_code: row.reason_code,
        severity: row.severity,
        action: row.action,
        status: row.status,
        assigned_owner: row.assigned_owner,
        internal_note: row.internal_note,
        metadata: row.metadata,
        created_at: row.created_at,
        updated_at: row.updated_at,
      })),
    };
  }

  async getSarReports(query: AdminMonitoringQueryDto) {
    const { page, limit } = this.toPaging(query);
    const qb = this.sarReportRepository
      .createQueryBuilder('s')
      .orderBy('s.created_at', 'DESC')
      .skip((page - 1) * limit)
      .take(limit);
    this.applyCommonFilters(qb, 's', query);
    if (query.severity && query.severity !== 'all') {
      const [min, max] =
        query.severity === 'HIGH'
          ? [80, null]
          : query.severity === 'MEDIUM'
            ? [50, 79]
            : [0, 49];
      qb.andWhere('s.risk_score >= :minRisk', { minRisk: min });
      if (max != null)
        qb.andWhere('s.risk_score <= :maxRisk', { maxRisk: max });
    }
    if (query.search) {
      qb.andWhere(
        '(s.risk_reason ILIKE :search OR CAST(s.user_id AS text) ILIKE :search OR CAST(s.transaction_id AS text) ILIKE :search)',
        { search: `%${query.search}%` },
      );
    }
    const [rows, total] = await Promise.all([qb.getMany(), qb.getCount()]);
    return {
      page,
      limit,
      total,
      data: rows.map((row) => ({
        id: row.id,
        user_id: row.user_id,
        transaction_id: row.transaction_id,
        risk_reason: row.risk_reason,
        risk_score: row.risk_score,
        severity:
          row.risk_score >= 80
            ? 'HIGH'
            : row.risk_score >= 50
              ? 'MEDIUM'
              : 'LOW',
        status: row.status,
        device_context: row.device_context,
        created_at: row.created_at,
      })),
    };
  }

  async getReconciliationIssues(query: AdminMonitoringQueryDto) {
    const { page, limit } = this.toPaging(query);
    const qb = this.reconciliationIssueRepository
      .createQueryBuilder('ri')
      .orderBy('ri.created_at', 'DESC')
      .skip((page - 1) * limit)
      .take(limit);
    this.applyCommonFilters(qb, 'ri', query);
    if (query.severity && query.severity !== 'all') {
      qb.andWhere('ri.severity = :severity', { severity: query.severity });
    }
    if (query.search) {
      qb.andWhere(
        '(ri.issue_type ILIKE :search OR ri.description ILIKE :search OR CAST(ri.id AS text) ILIKE :search)',
        { search: `%${query.search}%` },
      );
    }
    const [rows, total] = await Promise.all([qb.getMany(), qb.getCount()]);
    return {
      page,
      limit,
      total,
      data: rows.map((row) => ({
        id: row.id,
        report_date: row.report_date,
        issue_type: row.issue_type,
        severity: row.severity,
        description: row.description,
        status: row.status,
        metadata: row.metadata,
        created_at: row.created_at,
      })),
    };
  }

  async getAlerts(query: AdminRiskQueryDto) {
    const qb = this.riskRepository
      .createQueryBuilder('alert')
      .leftJoin(User, 'u', 'u.id = alert.user_id')
      .leftJoin(AppTransaction, 'tx', 'tx.id = alert.transaction_id')
      .select([
        'alert.id as id',
        'alert.type as type',
        'alert.severity as severity',
        'alert.user_id as user_id',
        'u.phone_number as user_phone',
        'alert.transaction_id as transaction_id',
        'alert.transaction_reference as transaction_reference',
        'alert.description as description',
        'alert.risk_score as risk_score',
        'alert.status as status',
        'alert.created_at as created_at',
        'alert.amount as alert_amount',
        'tx.amount as tx_amount',
        'tx.reference as tx_reference',
      ])
      .orderBy('alert.created_at', 'DESC');

    if (query.status && query.status !== 'all') {
      qb.andWhere('alert.status = :status', { status: query.status });
    }

    if (query.severity && query.severity !== 'all') {
      qb.andWhere('alert.severity = :severity', { severity: query.severity });
    }

    const rows = await qb.getRawMany();
    return rows.map((row) => {
      const fromAlert =
        row.alert_amount != null ? Number(row.alert_amount) : null;
      const fromTx = row.tx_amount != null ? Number(row.tx_amount) : null;
      const amount = fromAlert ?? fromTx ?? null;
      const reference =
        (row.transaction_reference as string | null)?.trim() ||
        (row.tx_reference as string | null)?.trim() ||
        null;
      return {
        id: row.id,
        type: row.type,
        severity: row.severity,
        user_id: row.user_id,
        user_phone: row.user_phone,
        transaction_id: row.transaction_id,
        transaction_reference: reference,
        description: row.description,
        risk_score: Number(row.risk_score || 0),
        status: row.status,
        created_at: row.created_at,
        amount,
      };
    });
  }

  async getStats() {
    const [totalAlerts, highSeverity, openCases] = await Promise.all([
      this.riskRepository.count(),
      this.riskRepository.count({ where: { severity: 'HIGH' } }),
      this.riskRepository.count({ where: { status: 'OPEN' } }),
    ]);

    const avgRow = await this.riskRepository
      .createQueryBuilder('alert')
      .select('COALESCE(AVG(alert.risk_score), 0)', 'avg')
      .getRawOne();

    return {
      totalAlerts,
      highSeverity,
      openCases,
      avgRiskScore: Number(avgRow?.avg || 0),
    };
  }

  async escalate(alertId: string, adminUser?: RequestUser) {
    const alert = await this.riskRepository.findOne({ where: { id: alertId } });
    if (!alert) {
      throw new NotFoundException('Risk alert not found');
    }

    alert.status = 'INVESTIGATING';
    await this.riskRepository.save(alert);

    await this.auditService.logAction({
      action: 'RISK_ALERT_ESCALATED',
      entityType: 'risk_alert',
      entityId: alert.id,
      userId: alert.user_id ?? undefined,
      adminUser,
    });

    return { success: true };
  }

  async flagTransaction(
    transactionId: string,
    reason: string,
    adminUser?: RequestUser,
  ) {
    const transaction = await this.transactionsRepository.findOne({
      where: { id: transactionId },
    });
    if (!transaction) {
      throw new NotFoundException('Transaction not found');
    }

    const alert = this.riskRepository.create({
      type: 'MANUAL_FLAG',
      severity: 'MEDIUM',
      user_id: transaction.sender_user_id,
      transaction_id: transaction.id,
      amount: Number(transaction.amount),
      transaction_reference: transaction.reference,
      description: reason,
      risk_score: 50,
      status: 'OPEN',
    });
    await this.riskRepository.save(alert);

    await this.auditService.logAction({
      action: 'TRANSACTION_FLAGGED',
      entityType: 'transaction',
      entityId: transaction.id,
      userId: transaction.sender_user_id ?? undefined,
      metadata: { reason },
      adminUser,
    });

    return { success: true };
  }

  async updateFraudEventStatus(
    id: string,
    payload: {
      status: 'OPEN' | 'REVIEWING' | 'RESOLVED' | 'FALSE_POSITIVE';
      assigned_owner?: string;
      internal_note?: string;
    },
    adminUser?: RequestUser,
  ) {
    const row = await this.fraudEventRepository.findOne({ where: { id } });
    if (!row) {
      throw new NotFoundException('Fraud event not found');
    }
    row.status = payload.status;
    if (payload.assigned_owner !== undefined) {
      row.assigned_owner = payload.assigned_owner || null;
    }
    if (payload.internal_note !== undefined) {
      row.internal_note = payload.internal_note || null;
    }
    await this.fraudEventRepository.save(row);
    await this.auditService.logAction({
      action: 'FRAUD_EVENT_STATUS_UPDATED',
      entityType: 'fraud_event',
      entityId: row.id,
      userId: row.user_id,
      metadata: {
        status: row.status,
        assigned_owner: row.assigned_owner,
      },
      adminUser,
    });
    return { success: true };
  }

  async updateSarStatus(id: string, status: string, adminUser?: RequestUser) {
    const row = await this.sarReportRepository.findOne({ where: { id } });
    if (!row) {
      throw new NotFoundException('SAR report not found');
    }
    const normalized =
      status === 'NEW'
        ? 'OPEN'
        : status === 'IN_REVIEW'
          ? 'UNDER_REVIEW'
          : status === 'FILED'
            ? 'REPORTED'
            : status;
    row.status = normalized;
    await this.sarReportRepository.save(row);
    await this.auditService.logAction({
      action: 'SAR_STATUS_UPDATED_BY_ADMIN',
      entityType: 'sar_report',
      entityId: row.id,
      userId: row.user_id,
      metadata: { status: row.status },
      adminUser,
    });
    return { success: true };
  }

  async updateReconciliationIssueStatus(
    id: string,
    status: string,
    adminUser?: RequestUser,
  ) {
    const row = await this.reconciliationIssueRepository.findOne({
      where: { id },
    });
    if (!row) {
      throw new NotFoundException('Reconciliation issue not found');
    }
    row.status = status;
    await this.reconciliationIssueRepository.save(row);
    await this.auditService.logAction({
      action: 'RECONCILIATION_ISSUE_STATUS_UPDATED',
      entityType: 'reconciliation_issue',
      entityId: row.id,
      metadata: { status: row.status },
      adminUser,
    });
    return { success: true };
  }
}

