    private readonly trustedDeviceRepository: Repository<TrustedDevice>,
    @InjectRepository(RiskAlert)
    private readonly riskAlertRepository: Repository<RiskAlert>,
    private readonly auditService: AdminAuditService,
    private readonly authzVersions: AuthzVersionService,
    private readonly unifiedIdentityService: UnifiedIdentityService,
  ) {}

  private applyUsersListFilters(
    qb: SelectQueryBuilder<User>,
    query: AdminUsersQueryDto,
  ) {
    if (query.status && query.status !== 'all') {
      qb.andWhere('u.status = :status', { status: query.status });
    }

    if (query.kyc && query.kyc !== 'all') {
      if (query.kyc === 'UNVERIFIED') {
        qb.andWhere('(k.status = :kyc OR k.status IS NULL)', {
          kyc: query.kyc,
        });
      } else {
        qb.andWhere('k.status = :kyc', { kyc: query.kyc });
      }
    }

    if (query.account_type && query.account_type !== 'all') {
      qb.andWhere('u.account_type = :account_type', {
        account_type: query.account_type,
      });
    }

    if (query.search) {
      qb.andWhere(
        '(u.phone_number ILIKE :search OR u.full_name ILIKE :search OR u.email ILIKE :search)',
        { search: `%${query.search}%` },
      );
    }
  }

  async getUsers(query: AdminUsersQueryDto) {
    const limit = Math.min(Number(query.limit) || 50, 500);
    const page = Math.max(1, Number(query.page) || 1);

    const countQb = this.usersRepository
      .createQueryBuilder('u')
      .leftJoin('u.kyc_profile', 'k');
    this.applyUsersListFilters(countQb, query);
    countQb.select('COUNT(DISTINCT u.id)', 'cnt');
    const cntRow = await countQb.getRawOne<{ cnt?: string }>();
    const total = Number(cntRow?.cnt ?? 0);

    const qb = this.usersRepository
      .createQueryBuilder('u')
      .leftJoin('u.kyc_profile', 'k')
      .select([
        'u.id as id',
        'u.phone_number as phone_number',
        'u.full_name as full_name',
        'u.email as email',
        'u.city as city',
        'u.account_type as account_type',
        'u.staff_role as staff_role',
        'u.linked_user_id as linked_user_id',
        'u.status as account_status',
        'u.risk_score as risk_score',
        'u.created_at as created_at',
        'u.last_login_at as last_login_at',
        "COALESCE(k.status, u.kyc_status, 'UNVERIFIED') as kyc_status",
      ])
      .orderBy('u.created_at', 'DESC');

    this.applyUsersListFilters(qb, query);

    qb.take(limit).skip((page - 1) * limit);

    const rows = await qb.getRawMany();
    const data = rows.map((row) => ({
      id: row.id,
      phone_number: row.phone_number,
      full_name: row.full_name,
      email: row.email,
      city: row.city ?? null,
      account_type: row.account_type || 'CONSUMER',
      staff_role: row.staff_role || 'ADMIN',
      linked_user_id: row.linked_user_id ?? null,
      kyc_status: row.kyc_status || 'UNVERIFIED',
      wallet_id: null,
      balance: 0,
      risk_score: Number(row.risk_score || 0),
      account_status: row.account_status,
      created_at: row.created_at,
      last_login_at: row.last_login_at,
    }));

    const total_pages = Math.max(1, Math.ceil(total / limit));

    return {
      data,
      total,
      page,
      limit,
      total_pages,
    };
  }

  async listSupportAgents() {
    const rows = await this.usersRepository.find({
      where: { account_type: 'ADMIN', staff_role: 'SUPPORT_AGENT' },
      select: [
        'id',
        'full_name',
        'email',
        'profile_photo_url',
        'status',
        'staff_role',
      ],
      order: { full_name: 'ASC', email: 'ASC' },
    });
    return {
      items: rows.map((row) => ({
        id: row.id,
        full_name: row.full_name ?? null,
        email: row.email ?? null,
        profile_photo_url: row.profile_photo_url ?? null,
        status: row.status,
        staff_role: row.staff_role || 'SUPPORT_AGENT',
      })),
    };
  }

  async createSupportAgent(
    input: CreateSupportAgentDto,
    adminUser?: RequestUser,
  ) {
    const email = (input.email || '').trim().toLowerCase();
    const fullName = (input.fullName || '').trim();
    const password = input.password ?? '';

    if (!email) {
      throw new BadRequestException('Email is required');
    }
    if (!fullName) {
      throw new BadRequestException('Full name is required');
    }
    if (password.length < 10) {
      throw new BadRequestException('Password must be at least 10 characters');
    }
    if (appConfig.adminEmails.includes(email)) {
      throw new BadRequestException(
        'This email is reserved for Super Admin bootstrap',
      );
    }

    const existing = await this.usersRepository.findOne({ where: { email } });
    if (existing) {
      throw new ConflictException('Email already in use');
    }

    const user = await this.usersRepository.save({
      phone_number: null,
      email,
      full_name: fullName,
      pin_hash: await hashPin(crypto.randomUUID()),
      staff_password_hash: await hashPassword(password),
      status: 'ACTIVE',
      kyc_status: 'APPROVED',
      account_type: 'ADMIN',
      staff_role: 'SUPPORT_AGENT',
    });

    await this.unifiedIdentityService.ensureIdentityForAdminUser(user.id);

    await this.auditService.logAction({
      action: 'SUPPORT_AGENT_CREATED',
      entityType: 'user',
      entityId: user.id,
      userId: user.id,
      metadata: { email, userId: user.id },
      adminUser,
    });

    return {
      id: user.id,
      email: user.email,
      fullName: user.full_name,
      staffRole: 'SUPPORT_AGENT' as const,
    };
  }

  async inviteAdmin(email: string, role: string) {
    if (!email || !email.trim()) {
      throw new BadRequestException('Email is required');
    }
    return {
      success: true,
      message:
        'Invite sent (stub). Implement email delivery and pending admin record.',
      email: email.trim(),
      role: role || 'ADMIN',
    };
  }

  /**
   * Check driver and courier accounts for linked consumer accounts
   */
  async checkDriverCourierConsumerAccounts() {
    const qb = this.usersRepository
      .createQueryBuilder('u')
      .leftJoin('u.linked_user', 'linked')
      .select([
        'u.id as id',
        'u.phone_number as phone_number',
        'u.full_name as full_name',
        'u.account_type as account_type',
        'u.linked_user_id as linked_user_id',
        'linked.id as linked_consumer_id',
        'linked.full_name as linked_consumer_name',
        'linked.phone_number as linked_consumer_phone',
        'linked.account_type as linked_account_type',
      ])
      .where('u.account_type IN (:...types)', { types: ['DRIVER', 'COURIER'] })
      .orderBy('u.account_type', 'ASC')
      .addOrderBy('u.full_name', 'ASC');

    const rows = await qb.getRawMany();

    // Also check for potential auto-links (same phone number)
    const accountsWithoutLink = rows.filter((r) => !r.linked_user_id);
    const potentialLinks: Array<{
      driver_courier_id: any;
      driver_courier_name: any;
      driver_courier_phone: any;
      account_type: any;
      potential_consumer_id: string;
      potential_consumer_name: string;
      potential_consumer_phone: string;
    }> = [];

    for (const account of accountsWithoutLink) {
      const consumer = await this.usersRepository.findOne({
        where: {
          phone_number: account.phone_number,
          account_type: 'CONSUMER',
        },
        select: ['id', 'full_name', 'phone_number'],
      });

      if (consumer) {
        potentialLinks.push({
          driver_courier_id: account.id,
          driver_courier_name: account.full_name,
          driver_courier_phone: account.phone_number,
          account_type: account.account_type,
          potential_consumer_id: consumer.id,
          potential_consumer_name: consumer.full_name,
          potential_consumer_phone: consumer.phone_number ?? '',
        });
      }
    }

    // Summary statistics
    const summary = {
      total_drivers: rows.filter((r) => r.account_type === 'DRIVER').length,
      drivers_with_link: rows.filter(
        (r) => r.account_type === 'DRIVER' && r.linked_user_id,
      ).length,
      drivers_without_link: rows.filter(
        (r) => r.account_type === 'DRIVER' && !r.linked_user_id,
      ).length,
      total_couriers: rows.filter((r) => r.account_type === 'COURIER').length,
      couriers_with_link: rows.filter(
        (r) => r.account_type === 'COURIER' && r.linked_user_id,
      ).length,
      couriers_without_link: rows.filter(
        (r) => r.account_type === 'COURIER' && !r.linked_user_id,
      ).length,
      potential_auto_links: potentialLinks.length,
    };

    return {
      accounts: rows.map((row) => ({
        id: row.id,
        phone_number: row.phone_number,
        full_name: row.full_name,
        account_type: row.account_type,
        linked_user_id: row.linked_user_id,
        linked_consumer: row.linked_consumer_id
          ? {
              id: row.linked_consumer_id,
              full_name: row.linked_consumer_name,
              phone_number: row.linked_consumer_phone,
              account_type: row.linked_account_type,
            }
          : null,
        has_linked_consumer: !!row.linked_user_id,
        has_valid_consumer_link:
          row.linked_user_id && row.linked_account_type === 'CONSUMER',
      })),
      potential_auto_links: potentialLinks,
      summary,
    };
  }

  async getUser(id: string) {
    const qb = this.usersRepository
      .createQueryBuilder('u')
      .leftJoin('u.kyc_profile', 'k')
      .leftJoin('u.linked_user', 'lu')
      .leftJoin('u.unified_identity', 'ui')
      .select([
        'u.id as id',
        'u.phone_number as phone_number',
        'u.full_name as full_name',
        'u.email as email',
        'u.city as user_city',
        'u.date_of_birth as date_of_birth',
        'u.nationality as nationality',
        'u.account_type as account_type',
        'u.staff_role as staff_role',
        'u.linked_user_id as linked_user_id',
        'u.unified_identity_id as unified_identity_id',
        'u.status as account_status',
        'u.risk_score as risk_score',
        'u.created_at as created_at',
        'u.last_login_at as last_login_at',
        'u.profile_photo_url as profile_photo_url',
        'u.deletion_status as deletion_status',
        'u.deletion_requested_at as deletion_requested_at',
        'u.deletion_scheduled_for as deletion_scheduled_for',
        'u.pii_anonymized_at as pii_anonymized_at',
        'ui.address as address',
        'ui.city as identity_city',
        'ui.profile_photo_url as identity_profile_photo_url',
        "COALESCE(k.status, u.kyc_status, 'UNVERIFIED') as kyc_status",
        'lu.id as linked_id',
        'lu.full_name as linked_full_name',
        'lu.phone_number as linked_phone_number',
      ])
      .where('u.id = :id', { id });

    const row = await qb.getRawOne();
    if (!row) {
      throw new NotFoundException('User not found');
    }

    const linked_user =
      row.linked_id != null
        ? {
            id: row.linked_id,
            full_name: row.linked_full_name,
            phone_number: row.linked_phone_number,
          }
        : null;

    const dob = row.date_of_birth;
    const dobStr =
      dob instanceof Date
        ? dob.toISOString().slice(0, 10)
        : dob != null
          ? String(dob).slice(0, 10)
          : null;

    const profilePhotoUrl =
      row.profile_photo_url || row.identity_profile_photo_url || null;

    const phones = row.unified_identity_id
      ? (
          await this.phoneNumbersRepository.find({
            where: { identity_id: row.unified_identity_id },
            order: { is_primary: 'DESC', created_at: 'ASC' },
          })
        ).map((p) => ({
          phone_number: p.phone_number,
          is_primary: p.is_primary,
          is_verified: p.is_verified,
          verified_at: p.verified_at,
        }))
      : [];

    return {
      id: row.id,
      phone_number: row.phone_number,
      full_name: row.full_name,
      email: row.email,
      city: row.identity_city || row.user_city || null,
      date_of_birth: dobStr,
      nationality: row.nationality ?? null,
      address: row.address ?? null,
      phones,
      account_type: row.account_type || 'CONSUMER',
      staff_role: row.staff_role || 'ADMIN',
      linked_user_id: row.linked_user_id ?? null,
      linked_user,
      kyc_status: row.kyc_status || 'UNVERIFIED',
      wallet_id: null,
      balance: 0,
      risk_score: Number(row.risk_score || 0),
      account_status: row.account_status,
      deletion_status: row.deletion_status ?? 'NONE',
      deletion_requested_at: row.deletion_requested_at ?? null,
      deletion_scheduled_for: row.deletion_scheduled_for ?? null,
      pii_anonymized_at: row.pii_anonymized_at ?? null,
      created_at: row.created_at,
      last_login_at: row.last_login_at,
      ...(profilePhotoUrl ? { profile_photo_url: profilePhotoUrl } : {}),
    };
  }

  async updateStaffRole(
    id: string,
    staffRole: StaffRole,
    adminUser?: RequestUser,
  ) {
    if (adminUser?.userId && adminUser.userId === id) {
      throw new ForbiddenException('Cannot change your own staff role');
    }
    if (staffRole !== 'ADMIN' && staffRole !== 'SUPPORT_AGENT') {
      throw new BadRequestException('Invalid staff role');
    }

    const user = await this.usersRepository.findOne({ where: { id } });
    if (!user) {
      throw new NotFoundException('User not found');
    }
    if (user.account_type !== 'ADMIN') {
      throw new BadRequestException(
        'Staff role can only be set on ADMIN accounts',
      );
    }

    const from = user.staff_role || 'ADMIN';
    user.staff_role = staffRole;
    await this.usersRepository.save(user);
    await this.authzVersions.bump(id);
    await this.refreshTokenRepository
      .createQueryBuilder()
      .update()
      .set({ revoked_at: new Date() })
      .where('user_id = :userId', { userId: id })
      .andWhere('revoked_at IS NULL')
      .execute();
    await this.auditService.logAction({
      action: 'STAFF_ROLE_CHANGED',
      entityType: 'user',
      entityId: id,
      userId: id,
      metadata: { from, to: staffRole },
      adminUser,
    });
    return { success: true, staff_role: staffRole };
  }

  async updateStatus(id: string, status: string, adminUser?: RequestUser) {
    const user = await this.usersRepository.findOne({ where: { id } });
    if (!user) {
      throw new NotFoundException('User not found');
    }

    user.status = status;
    await this.usersRepository.save(user);
    if (status === 'FROZEN' || status === 'SUSPENDED' || status === 'BANNED') {
      await this.authzVersions.bump(id);
    }

    await this.auditService.logAction({
      action: 'USER_STATUS_UPDATED',
      entityType: 'user',
      entityId: id,
      userId: id,
      metadata: { status },
      adminUser,
    });

    return { success: true };
  }

  async freezeUser(userId: string, adminUser?: RequestUser) {
    const user = await this.usersRepository.findOne({ where: { id: userId } });
    if (!user) {
      throw new NotFoundException('User not found');
    }

    user.status = 'FROZEN';
    await this.usersRepository.save(user);
    // SEC-003: invalidate outstanding ADMIN access JWTs via authz_version bump.
    await this.authzVersions.bump(userId);

    const wallet = await this.walletsRepository.findOne({
      where: { user_id: userId },
    });
    if (wallet) {
      wallet.status = 'LOCKED';
      await this.walletsRepository.save(wallet);
    }

    await this.auditService.logAction({
      action: 'WALLET_FROZEN',
      entityType: 'wallet',
      entityId: wallet?.id,
      userId: userId,
      adminUser,
    });

    return { success: true };
  }

  async unfreezeUser(userId: string, adminUser?: RequestUser) {
    const user = await this.usersRepository.findOne({ where: { id: userId } });
    if (!user) {
      throw new NotFoundException('User not found');
    }

    user.status = 'ACTIVE';
    await this.usersRepository.save(user);

    const wallet = await this.walletsRepository.findOne({
      where: { user_id: userId },
    });
    if (wallet) {
      wallet.status = 'ACTIVE';
      await this.walletsRepository.save(wallet);
    }

    await this.auditService.logAction({
      action: 'WALLET_UNFROZEN',
      entityType: 'wallet',
      entityId: wallet?.id,
      userId: userId,
      adminUser,
    });

    return { success: true };
  }

  async getUserWallet(id: string) {
    const wallet = await this.walletsRepository.findOne({
      where: { user_id: id },
    });
    if (!wallet) {
      throw new NotFoundException('Wallet not found');
    }
    return wallet;
  }

  async getUserKyc(id: string) {
    const kyc = await this.kycRepository.findOne({ where: { user_id: id } });
    if (!kyc) {
      throw new NotFoundException('KYC profile not found');
    }
    return kyc;
  }

  async forceLogoutUser(userId: string, adminUser?: RequestUser) {
    const user = await this.usersRepository.findOne({ where: { id: userId } });
    if (!user) {
      throw new NotFoundException('User not found');
    }
    await this.refreshTokenRepository
      .createQueryBuilder()
      .update()
      .set({ revoked_at: new Date() })
      .where('user_id = :userId', { userId })
      .andWhere('revoked_at IS NULL')
      .execute();
    // SEC-003: bump authz_version so outstanding ADMIN access JWTs fail RolesGuard.
    await this.authzVersions.bump(userId);
    await this.auditService.logAction({
      action: 'USER_FORCE_LOGOUT',
      entityType: 'user',
      entityId: userId,
      userId,
      adminUser,
    });
    return { success: true };
  }

  /** Demote ADMIN → CONSUMER and invalidate JWT privilege immediately (SEC-003). */
  async demoteAdmin(userId: string, adminUser?: RequestUser) {
    const user = await this.usersRepository.findOne({ where: { id: userId } });
    if (!user) {
      throw new NotFoundException('User not found');
    }
    if (user.account_type !== 'ADMIN') {
      throw new BadRequestException('User is not an administrator');
    }
    user.account_type = 'CONSUMER';
    await this.usersRepository.save(user);
    await this.authzVersions.bump(userId);
    await this.refreshTokenRepository
      .createQueryBuilder()
      .update()
      .set({ revoked_at: new Date() })
      .where('user_id = :userId', { userId })
      .andWhere('revoked_at IS NULL')
      .execute();
    await this.auditService.logAction({
      action: 'ADMIN_DEMOTED',
      entityType: 'user',
      entityId: userId,
      userId,
      adminUser,
    });
    return { success: true };
  }

  async untrustDevice(
    userId: string,
    deviceId: string,
    adminUser?: RequestUser,
  ) {
    const user = await this.usersRepository.findOne({ where: { id: userId } });
    if (!user) throw new NotFoundException('User not found');
    const row = await this.trustedDeviceRepository.findOne({
      where: { user_id: userId, device_id: deviceId },
    });
    if (!row) throw new NotFoundException('Trusted device not found');
    row.trusted = false;
    row.last_seen_at = new Date();
    await this.trustedDeviceRepository.save(row);
    await this.refreshTokenRepository
      .createQueryBuilder()
      .update()
      .set({ revoked_at: new Date() })
      .where('user_id = :userId', { userId })
      .andWhere('device_id = :deviceId', { deviceId })
      .andWhere('revoked_at IS NULL')
      .execute();
    await this.auditService.logAction({
      action: 'DEVICE_UNTRUSTED_BY_ADMIN',
      entityType: 'trusted_device',
      entityId: row.id,
      userId,
      metadata: { deviceId },
      adminUser,
    });
    return { success: true };
  }

  async triggerStepUp(userId: string, reason: string, adminUser?: RequestUser) {
    const user = await this.usersRepository.findOne({ where: { id: userId } });
    if (!user) throw new NotFoundException('User not found');
    await this.riskAlertRepository.save({
      type: 'MANUAL_STEP_UP_REQUIRED',
      severity: 'MEDIUM',
      user_id: userId,
      transaction_id: null,
      description: reason || 'Manual step-up auth required by admin',
      risk_score: 60,
      status: 'OPEN',
    });
    await this.auditService.logAction({
      action: 'STEP_UP_FORCED_BY_ADMIN',
      entityType: 'user',
      entityId: userId,
      userId,
      metadata: { reason },
      adminUser,
    });
    return { success: true };
  }

  async addComplianceTag(userId: string, tag: string, adminUser?: RequestUser) {
    const user = await this.usersRepository.findOne({ where: { id: userId } });
    if (!user) throw new NotFoundException('User not found');
    await this.riskAlertRepository.save({
      type: `USER_TAG_${tag.toUpperCase()}`,
      severity: 'MEDIUM',
      user_id: userId,
      transaction_id: null,
      description: `Compliance tag applied: ${tag}`,
      risk_score: 55,
      status: 'OPEN',
    });
    await this.auditService.logAction({
      action: 'COMPLIANCE_TAG_ADDED',
      entityType: 'user',
      entityId: userId,
      userId,
      metadata: { tag },
      adminUser,
    });
    return { success: true };
  }
}

import { MiddlewareConsumer, Module, NestModule } from '@nestjs/common';
import { JwtModule } from '@nestjs/jwt';
import { PassportModule } from '@nestjs/passport';
import { TypeOrmModule } from '@nestjs/typeorm';
import { AuthController } from './auth.controller';
import { AuthService } from './auth.service';
import { User } from '../users/entities/user.entity';
import { OtpCode } from './entities/otp-code.entity';
import { OtpSession } from './entities/otp-session.entity';
import { OtpAttempt } from './entities/otp-attempt.entity';
import { PinAttempt } from './entities/pin-attempt.entity';
import { RefreshToken } from './entities/refresh-token.entity';
import { TrustedDevice } from './entities/trusted-device.entity';
import { OtpLockoutService } from './otp-lockout.service';
import { PinLockoutService } from './pin-lockout.service';
import { OtpSendRateLimitService } from './otp-send-rate-limit.service';
import { OtpVerifyRateLimitService } from './otp-verify-rate-limit.service';
import { OtpSendRateLimitGuard } from './guards/otp-send-rate-limit.guard';
import { OtpVerifyRateLimitGuard } from './guards/otp-verify-rate-limit.guard';
import { JwtStrategy } from './strategies/jwt.strategy';
import { JwtKeysService } from '../jwks/jwt-keys.service';
import {
  getJwtAccessExpiresIn,
  getJwtAudience,
  getJwtIssuer,
} from '../../common/security/jwt-claims';
import { UsersModule } from '../users/users.module';
import { AuditModule } from '../audit/audit.module';
import { AuditLog } from '../audit/entities/audit-log.entity';
import { RiskAlert } from '../admin/entities/risk-alert.entity';
import { KycProfile } from '../compliance/entities/kyc-profile.entity';
import { RiskAuthMiddleware } from '../../common/middleware/risk_auth.middleware';
import { SecurityEventsModule } from '../security-events/security-events.module';
import { AuthzModule } from '../authz/authz.module';

@Module({
  imports: [
    TypeOrmModule.forFeature([
      User,
      OtpCode,
      OtpSession,
      OtpAttempt,
      PinAttempt,
      RefreshToken,
      TrustedDevice,
      AuditLog,
      RiskAlert,
      KycProfile,
    ]),
    PassportModule,
    JwtModule.registerAsync({
      inject: [JwtKeysService],
      useFactory: (keys: JwtKeysService) => ({
        privateKey: keys.privateKey,
        publicKey: keys.publicKey,
        signOptions: {
          algorithm: 'RS256',
          expiresIn: getJwtAccessExpiresIn(),
          keyid: keys.kid,
          issuer: getJwtIssuer(),
          audience: getJwtAudience(),
        } as any,
      }),
    }),
    UsersModule,
    AuditModule,
    SecurityEventsModule,
    AuthzModule,
  ],
  controllers: [AuthController],
  providers: [
    AuthService,
    JwtStrategy,
    OtpLockoutService,
    PinLockoutService,
    OtpSendRateLimitService,
    OtpVerifyRateLimitService,
    OtpSendRateLimitGuard,
    OtpVerifyRateLimitGuard,
  ],
  exports: [AuthService, AuthzModule],
})
export class AuthModule implements NestModule {
  configure(consumer: MiddlewareConsumer) {
    consumer
      .apply(RiskAuthMiddleware)
      .forRoutes(
        'auth/verify-pin',
        'auth/pin/verify',
        'pay/auth/verify-pin',
        'pay/auth/pin/verify',
      );
  }
}

