import { Injectable } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { JwtKeysService } from '../../jwks/jwt-keys.service';
import type { Request } from 'express';
import { extractBearerAccessToken } from '../security/bearer-access-token';
import {
  getJwtAudience,
  getJwtIssuer,
} from '../../../common/security/jwt-claims';

export interface JwtPayload {
  sub: string;
  phone_number?: string;
  role?: string;
  roles?: string[];
  email?: string;
  type?: string;
  account_type?: string;
  unified_identity_id?: string;
  session_id?: string;
  auth_method?: string;
  kyc_verified?: boolean;
  kyc_tier?: string;
  /** SEC-003 admin authz version */
  av?: number;
  iss?: string;
  aud?: string | string[];
}

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(private readonly jwtKeys: JwtKeysService) {
    super({
      jwtFromRequest: ExtractJwt.fromExtractors([
        (request: Request) => extractBearerAccessToken(request),
      ]),
      ignoreExpiration: false,
      secretOrKey: jwtKeys.publicKey,
      algorithms: ['RS256'],
      issuer: getJwtIssuer(),
      audience: getJwtAudience(),
    });
  }

  async validate(payload: JwtPayload) {
    if (payload.type === 'otp_session' || payload.type === 'identity_session') {
      return {
        userId: payload.sub,
        type: payload.type,
        phone_number: payload.phone_number,
        unified_identity_id: payload.unified_identity_id,
      };
    }
    return {
      userId: payload.sub,
      account_type: payload.account_type ?? 'CONSUMER',
      unified_identity_id: payload.unified_identity_id,
      session_id: payload.session_id,
      auth_method: payload.auth_method,
      role: payload.role,
      roles: payload.roles,
      email: payload.email,
      phone_number: payload.phone_number,
      kyc_verified: payload.kyc_verified === true,
      kyc_tier: payload.kyc_tier,
      authz_version: payload.av,
      av: payload.av,
    };
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { In, MoreThanOrEqual, Repository } from 'typeorm';
import { SarReport } from './entities/sar-report.entity';
import { FraudEvent } from '../fraud/entities/fraud-event.entity';
import { AuditService } from '../audit/audit.service';
import { SarQueryDto } from './dto/sar.query.dto';

export interface SarDeviceContext {
  device_id?: string;
  device_integrity?: string;
  user_agent?: string;
}

export interface SarEvaluationInput {
  user_id: string;
  transaction_id?: string | null;
  transaction_reference?: string | null;
  highest_risk_score: number;
  reason_codes: string[];
  device_context?: SarDeviceContext;
}

@Injectable()
export class SarService {
  constructor(
    @InjectRepository(SarReport)
    private readonly sarRepository: Repository<SarReport>,
    @InjectRepository(FraudEvent)
    private readonly fraudEventRepository: Repository<FraudEvent>,
    private readonly auditService: AuditService,
  ) {}

  private get riskScoreThreshold(): number {
    return Number(process.env.SAR_RISK_SCORE_THRESHOLD ?? 75);
  }

  private get repeatedPatternThreshold(): number {
    return Number(process.env.SAR_REPEATED_PATTERN_THRESHOLD ?? 3);
  }

  private get repeatedPatternWindowHours(): number {
    return Number(process.env.SAR_REPEATED_PATTERN_WINDOW_HOURS ?? 24);
  }

  private get suspiciousReasonCodes(): string[] {
    const raw =
      process.env.SAR_SUSPICIOUS_REASON_CODES ??
      'FAILED_PIN_THEN_HIGH_VALUE,VELOCITY_THRESHOLD_EXCEEDED,RAPID_BALANCE_DRAIN_DETECTED';
    return raw
      .split(',')
      .map((code) => code.trim())
      .filter(Boolean);
  }

  async evaluateAndCreate(
    input: SarEvaluationInput,
  ): Promise<SarReport | null> {
    const thresholdExceeded =
      input.highest_risk_score >= this.riskScoreThreshold;
    const repeatedPatternDetected =
      await this.hasRepeatedSuspiciousPatterns(input);
    if (!thresholdExceeded && !repeatedPatternDetected) {
      return null;
    }

    const riskReason = thresholdExceeded
      ? `RISK_SCORE_THRESHOLD_EXCEEDED:${input.reason_codes.join('|')}`
      : `REPEATED_SUSPICIOUS_PATTERN:${input.reason_codes.join('|')}`;
    const reportPayload = {
      userId: input.user_id,
      transactionId: input.transaction_id ?? null,
      transactionReference: input.transaction_reference ?? null,
      risk_reason: riskReason,
      risk_score: input.highest_risk_score,
      timestamp: new Date().toISOString(),
      device_context: input.device_context ?? {},
      trigger_type: thresholdExceeded ? 'RISK_SCORE' : 'REPEATED_PATTERN',
      source: 'fraud_rules_engine',
    };

    const sar = this.sarRepository.create({
      user_id: input.user_id,
      transaction_id: input.transaction_id ?? null,
      risk_reason: riskReason.slice(0, 120),
      risk_score: input.highest_risk_score,
      device_context: (input.device_context as Record<string, unknown>) ?? null,
      report_payload: reportPayload,
      status: 'OPEN',
    });
    const savedSar = await this.sarRepository.save(sar);

    await this.auditService
      .audit({
        actorUserId: input.user_id,
        action: 'SAR_CREATED',
        targetType: 'SAR_REPORT',
        targetId: savedSar.id,
        metadata: {
          transaction_id: input.transaction_id ?? null,
          risk_reason: riskReason,
          risk_score: input.highest_risk_score,
          trigger_type: thresholdExceeded ? 'RISK_SCORE' : 'REPEATED_PATTERN',
        },
      })
      .catch(() => {});

    return savedSar;
  }

  private async hasRepeatedSuspiciousPatterns(
    input: SarEvaluationInput,
  ): Promise<boolean> {
    const reasons = input.reason_codes.filter((reason) =>
      this.suspiciousReasonCodes.includes(reason),
    );
    if (reasons.length === 0) return false;
    const windowStart = new Date(
      Date.now() - this.repeatedPatternWindowHours * 60 * 60 * 1000,
    );
    const count = await this.fraudEventRepository.count({
      where: {
        user_id: input.user_id,
        reason_code: In(reasons),
        created_at: MoreThanOrEqual(windowStart),
      },
    });
    return count >= this.repeatedPatternThreshold;
  }

  async listSarReports(query: SarQueryDto) {
    const where =
      query.status && query.status !== 'all' ? { status: query.status } : {};
    const rows = await this.sarRepository.find({
      where,
      order: { created_at: 'DESC' },
      take: 1000,
    });
    return rows.map((row) => ({
      id: row.id,
      userId: row.user_id,
      transactionId: row.transaction_id,
      risk_reason: row.risk_reason,
      risk_score: row.risk_score,
      timestamp: row.created_at,
      device_context: row.device_context,
      status: row.status,
      report_payload: row.report_payload,
    }));
  }

  async exportSarReportsCsv(query: SarQueryDto): Promise<string> {
    const rows = await this.listSarReports({ ...query, format: 'json' });
    const headers = [
      'id',
      'userId',
      'transactionId',
      'risk_reason',
      'risk_score',
      'timestamp',
      'status',
      'device_context',
      'report_payload',
    ];
    const body = rows.map((row) => [
      row.id,
      row.userId,
      row.transactionId ?? '',
      row.risk_reason,
      row.risk_score,
      row.timestamp instanceof Date
        ? row.timestamp.toISOString()
        : String(row.timestamp),
      row.status,
      JSON.stringify(row.device_context ?? {}),
      JSON.stringify(row.report_payload ?? {}),
    ]);
    return [
      headers.join(','),
      ...body.map((line) =>
        line.map((value) => this.escapeCsv(value)).join(','),
      ),
    ].join('\n');
  }

  async updateSarStatus(id: string, status: string, adminUserId?: string) {
    const sar = await this.sarRepository.findOne({ where: { id } });
    if (!sar) {
      throw new NotFoundException('SAR report not found');
    }
    sar.status = status;
    const saved = await this.sarRepository.save(sar);
    await this.auditService
      .audit({
        actorUserId: adminUserId ?? null,
        action: 'SAR_STATUS_UPDATED',
        targetType: 'SAR_REPORT',
        targetId: saved.id,
        metadata: { status: saved.status },
      })
      .catch(() => {});
    return {
      id: saved.id,
      status: saved.status,
      updated_at: saved.updated_at,
    };
  }

  private escapeCsv(value: unknown): string {
    if (value == null) return '';
    const text = String(value);
    if (text.includes(',') || text.includes('"') || text.includes('\n')) {
      return `"${text.replace(/"/g, '""')}"`;
    }
    return text;
  }
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import {
  SecurityEvent,
  type SecurityEventType,
} from './entities/security-event.entity';
import { QuerySecurityEventsDto } from './dto/query-security-events.dto';

export interface CreateSecurityEventInput {
  user_id?: string | null;
  event_type: SecurityEventType;
  metadata?: Record<string, unknown> | null;
  ip_address?: string | null;
  device_id?: string | null;
}

@Injectable()
export class SecurityEventsService {
  constructor(
    @InjectRepository(SecurityEvent)
    private readonly securityEventRepository: Repository<SecurityEvent>,
  ) {}

  /**
   * High-volume path uses insert() (no entity hydration, no SELECT roundtrip).
   */
  async logEvent(input: CreateSecurityEventInput): Promise<void> {
    await this.securityEventRepository.insert({
      user_id: input.user_id ?? null,
      event_type: input.event_type,
      metadata: input.metadata ?? null,
      ip_address: input.ip_address ?? null,
      device_id: input.device_id ?? null,
    } as any);
  }

  async queryEvents(query: QuerySecurityEventsDto) {
    const limit = Math.min(query.limit ?? 100, 1000);
    const qb = this.securityEventRepository
      .createQueryBuilder('e')
      .orderBy('e.created_at', 'DESC')
      .take(limit);

    if (query.user_id) {
      qb.andWhere('e.user_id = :userId', { userId: query.user_id });
    }
    if (query.event_type) {
      qb.andWhere('e.event_type = :eventType', { eventType: query.event_type });
    }

    const rows = await qb.getMany();
    return rows.map((row) => ({
      id: row.id,
      user_id: row.user_id,
      event_type: row.event_type,
      metadata: row.metadata,
      ip: row.ip_address,
      deviceId: row.device_id,
      timestamp: row.created_at,
    }));
  }
}

import {
  Injectable,
  NotFoundException,
  ConflictException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { EntityManager, Repository } from 'typeorm';
import { IdentityPhoneNumber } from './entities/identity-phone-number.entity';
import { UnifiedIdentity } from './entities/unified-identity.entity';
import {
  normalizePhoneNumber,
  tryNormalizePhoneNumber,
} from '../../common/phone/phone-normalizer';

@Injectable()
export class IdentityPhoneNumbersService {
  constructor(
    @InjectRepository(IdentityPhoneNumber)
    private readonly repo: Repository<IdentityPhoneNumber>,
    @InjectRepository(UnifiedIdentity)
    private readonly identityRepo: Repository<UnifiedIdentity>,
  ) {}

  /**
   * Normalize phone to E.164. Re-export for convenience.
   */
  normalizePhoneNumber(raw: string): string {
    return normalizePhoneNumber(raw);
  }

  /** Try to normalize; returns null on failure. */
  tryNormalize(raw: string): string | null {
    return tryNormalizePhoneNumber(raw);
  }

  /**
   * Find identity by phone (via identity_phone_numbers).
   * Normalizes input before lookup. Returns null if not found.
   */
  async findIdentityByPhone(rawPhone: string): Promise<UnifiedIdentity | null> {
    const normalized = tryNormalizePhoneNumber(rawPhone);
    if (!normalized) return null;
    const row = await this.repo.findOne({
      where: { normalized_phone_number: normalized },
      relations: ['identity'],
    });
    return row?.identity ?? null;
  }

  /**
   * Find identity id by phone. Returns null if not found.
   */
  async findIdentityIdByPhone(rawPhone: string): Promise<string | null> {
    const normalized = tryNormalizePhoneNumber(rawPhone);
    if (!normalized) return null;
    const row = await this.repo.findOne({
      where: { normalized_phone_number: normalized },
      select: ['identity_id'],
    });
    return row?.identity_id ?? null;
  }

  /**
   * Attach a phone number to an identity.
   * Normalizes before storing. If number already linked to another identity, throws Conflict.
   * @param manager - Optional. When inside a transaction, pass the EntityManager so the identity
   *   lookup can see uncommitted rows (e.g. a freshly created unified_identity).
   */
  async attachPhoneNumberToIdentity(
    identityId: string,
    rawPhone: string,
    options?: { isPrimary?: boolean; isVerified?: boolean },
    manager?: EntityManager,
  ): Promise<IdentityPhoneNumber> {
    const identityRepo = manager
      ? manager.getRepository(UnifiedIdentity)
      : this.identityRepo;
    const repo = manager
      ? manager.getRepository(IdentityPhoneNumber)
      : this.repo;

    const identity = await identityRepo.findOne({
      where: { id: identityId },
    });
    if (!identity) {
      throw new NotFoundException('Identity not found');
    }
    const normalized = normalizePhoneNumber(rawPhone);
    const existing = await repo.findOne({
      where: { normalized_phone_number: normalized },
    });
    if (existing) {
      if (existing.identity_id === identityId) {
        return existing;
      }
      throw new ConflictException(
        'This phone number is already linked to another identity',
      );
    }
    const isFirst =
      (await repo.count({ where: { identity_id: identityId } })) === 0;
    const isPrimary = options?.isPrimary ?? isFirst;
    const isVerified = options?.isVerified ?? false;
    if (isPrimary) {
      await repo.update({ identity_id: identityId }, { is_primary: false });
    }
    const row = repo.create({
      identity_id: identityId,
      phone_number: rawPhone,
      normalized_phone_number: normalized,
      is_primary: isPrimary,
      is_verified: isVerified,
      verified_at: isVerified ? new Date() : null,
    });
    try {
      return await repo.save(row);
    } catch (e: any) {
      if (e?.code === '23505') {
        const existingRow = await repo.findOne({
          where: { normalized_phone_number: normalized },
        });
        if (existingRow?.identity_id === identityId) {
          return existingRow;
        }
        throw new ConflictException(
          'This phone number is already linked to another identity',
        );
      }
      throw e;
    }
  }

  /**
   * Set the primary phone number for an identity.
   */
  async setPrimaryPhoneNumber(
    identityId: string,
    rawPhone: string,
  ): Promise<IdentityPhoneNumber> {
    const normalized = normalizePhoneNumber(rawPhone);
    const row = await this.repo.findOne({
      where: {
        identity_id: identityId,
        normalized_phone_number: normalized,
      },
    });
    if (!row) {
      throw new NotFoundException('Phone number not found for this identity');
    }
    await this.repo.update({ identity_id: identityId }, { is_primary: false });
    row.is_primary = true;
    return this.repo.save(row);
  }

  /**
   * Mark a phone number as verified.
   */
  async verifyPhoneNumber(
    identityId: string,
    rawPhone: string,
  ): Promise<IdentityPhoneNumber> {
    const normalized = normalizePhoneNumber(rawPhone);
    const row = await this.repo.findOne({
      where: {
        identity_id: identityId,
        normalized_phone_number: normalized,
      },
    });
    if (!row) {
      throw new NotFoundException('Phone number not found for this identity');
    }
    row.is_verified = true;
    row.verified_at = new Date();
    return this.repo.save(row);
  }

  /**
   * Get primary phone for an identity, or first phone if none primary.
   */
  async getPrimaryPhone(identityId: string): Promise<string | null> {
    const primary = await this.repo.findOne({
      where: { identity_id: identityId, is_primary: true },
      select: ['phone_number'],
    });
    if (primary) return primary.phone_number;
    const first = await this.repo.findOne({
      where: { identity_id: identityId },
      order: { created_at: 'ASC' },
      select: ['phone_number'],
    });
    return first?.phone_number ?? null;
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { UnifiedIdentity } from './entities/unified-identity.entity';
import { User } from './entities/user.entity';
import {
  SharedField,
  NexaService,
  PROFILE_SYNC_RULES,
